const sid=id=>id.startsWith('ground-')?id:'ground-'+id;
const P=(text,...sources)=>({text,sources:sources.flat().map(sid)});
const supplier=(name,offering,note,...sources)=>({name,offering,note,sources:sources.flat().map(sid)});
const alternative=(name,description,tradeoff,...sources)=>({name,description,tradeoff,sources:sources.flat().map(sid)});
const term=(term,definition)=>({term,definition});
const S=(id,title,paragraphs)=>({id,title,paragraphs:Array.isArray(paragraphs)?paragraphs:[paragraphs]});
function article(key,summary,purpose,operation,engineering,extras={}){
 const sections=[S('purpose','Purpose and place in the system',purpose),S('operation','How it works',operation),S('engineering','Interfaces and design choices',engineering)];
 const value={key:'ground-'+key,summary,sections,suppliers:[],alternatives:[],inspection:[],terms:[],relatedIds:[],...extras};
 value.sourceIds=[...new Set([...(extras.sourceIds||[]).map(sid),...value.sections.flatMap(s=>s.paragraphs.flatMap(p=>p.sources||[])),...value.suppliers.flatMap(s=>s.sources||[]),...value.alternatives.flatMap(a=>a.sources||[])])];
 return value;
}
const topics={};
topics.facility=article('facility',
 'A payload-processing facility is the temporary home of the spacecraft between transport and launch. Its rooms, utilities, handling equipment and control interfaces let teams inspect the delivered article, complete integration, demonstrate that it works, and hand it over to the launch provider.',
 P('The facility is part of the mission’s test and logistics system. A cleanroom protects exposed surfaces; nearby control rooms keep people and noisy equipment away from the article; service areas support tools, consumables and test racks. Astrotech’s published processing flow is a useful real-world example of these functions. A building’s appearance alone says little about which operations it can support.','astrotech'),
 P('The spacecraft moves through a controlled sequence of configurations. Shipping restraints and protective covers are removed when their jobs are complete, test connections are added for checkout, and flight covers or fairing hardware are fitted before transfer. Each configuration needs its own space, access, electrical interfaces and handling path. A planned route must accommodate the spacecraft together with its lifting fixture and transport envelope.'),
 P('Useful facility questions include clear door and hook heights, floor loading, crane coverage, cleanliness, communications access, fluid interfaces and proximity to the pad. Some projects process almost entirely in a provider’s building; others use an independent payload facility and transfer an encapsulated assembly. Neither arrangement removes the need to agree responsibility at every handover.','falcon','ariane'),
 {suppliers:[supplier('Astrotech Space Operations','Payload-processing facilities and campaign services','A real service-provider example; the selected study facility is identified separately in the configuration.','astrotech')],alternatives:[alternative('Provider-integrated processing','Keep payload operations close to the vehicle integration team.','Facility availability and access follow the provider’s campaign schedule.'),alternative('Independent processing facility','Complete customer operations in a dedicated facility before transfer.','Transport, interface handover and continuity of environmental control need their own plan.','astrotech')],inspection:['Follow the clear route between the spacecraft stand, handling fixtures and launch interface. The rendered building is a schematic layout.'],terms:[term('AIT','Assembly, integration and test: the campaign that turns delivered equipment into a verified spacecraft.'),term('EGSE / MGSE','Electrical / mechanical ground support equipment.')],relatedIds:['ground:checkout','ground:bridge-crane','ground:environment','site:launch-position']});
topics.checkout=article('checkout',
 'The checkout console coordinates a spacecraft rehearsal. It sends commands, supplies simulated indications and collects the responses that show whether the integrated vehicle follows its intended sequence. It is the operator’s view of the test, while specialized racks provide the physical interfaces.',
 P('A subsystem can pass its own bench test and still interact incorrectly with its neighbors. A mission rehearsal therefore follows a complete chain: an indication is received, flight software changes state, the correct equipment is enabled, and telemetry confirms the result. NASA’s day-in-the-life guidance treats these integrated scenarios as a distinct and valuable part of spacecraft testing.','ditl'),
 P('The console runs a versioned procedure against a known hardware configuration. Front-end electronics translate its commands into the spacecraft’s actual interfaces; a mission database gives received fields their meanings and units. Time-stamped records connect each requested action with the response. An inhibit can keep a real mechanism stationary while the test exercises the logic around its simulated release.'),
 P('The important boundary is between the test environment and flight behavior. Replacing a sensor with a simulator proves only the functions downstream of that interface. A useful result identifies which hardware, software, calibration data and procedure were involved. Terma’s CCS5 and TSC illustrate how commercial checkout systems separate test conduct, interfaces and data analysis.','terma-checkout'),
 {suppliers:[supplier('Terma','CCS5 and Test Sequence Controller','Examples of central spacecraft checkout software; no commercial checkout package is installed by this browser model.','terma-checkout')],alternatives:[alternative('Scripted unit bench','Exercise a small component directly with simple equipment.','Fast to diagnose, but it omits interactions with the integrated spacecraft.'),alternative('Full mission rehearsal','Connect flight software, representative interfaces and operations procedures.','Requires more integration work and careful control of what is simulated.','ditl')],inspection:['Find the console and its test connections, then use the linked flight avionics page to distinguish the ground operator from the onboard controller.'],terms:[term('Inhibit','A condition that prevents a command from energizing or releasing hardware.'),term('Telemetry','Measurements and status reported by the spacecraft.')],relatedIds:['ground:avionics','ground:orbit','flight:08.01']});
topics.compute=article('compute',
 'The payload test rack demonstrates that the data-center payload can do useful work before launch. It supplies jobs, observes results and correlates computing performance with memory use, electrical demand and heat production. A powered-on accelerator is only the beginning of that demonstration.',
 P('For an orbital data center, the acceptance question is whether an Earth customer receives the intended result at the intended service level. The workload must therefore identify its model, precision, input sizes, concurrency and output-quality requirement. MLPerf’s published benchmark methodology is a useful example of defining a repeatable workload before comparing machines.','mlperf','mlperf-docs'),
 P('The rack acts as the customer and as the measuring system. It can feed a known job through the payload interfaces, collect timing and resource measurements, and check the returned artifact. Different tests expose different limits: a short response may be dominated by startup or scheduling, while a long batch may saturate memory movement or heat rejection. Ground cooling and power equipment must support the intended operating point.'),
 P('A meaningful comparison keeps the success criterion fixed. Higher throughput obtained by allowing much longer delays is not the same result as meeting an interactive response target. Likewise, a completed training run needs a usable output and documented software configuration. The test rack connects these workload results to the spacecraft’s power, thermal and data-transfer allocations instead of treating processor arithmetic alone as mission performance.'),
 {suppliers:[supplier('Terma','Payload electrical ground support equipment','An example of configurable payload interfaces and automated testing; the AI workload harness would be project-specific.','terma-payload'),supplier('MLCommons','MLPerf benchmark definitions','A measurement reference and software ecosystem, not the maker of the depicted rack.','mlperf')],alternatives:[alternative('Representative compute workload','Run the actual software stack with a controlled job set.','Best for service validation; results depend on the workload and software versions.'),alternative('Electrical or thermal load emulator','Replace computation with a known power or heat load.','Useful for utility testing, but it cannot demonstrate correct AI output.')],inspection:['The rack represents test instrumentation. Open the accelerator, host and cooling pages to inspect the equipment actually flying.'],terms:[term('Throughput','Completed work per unit time.'),term('Latency','Elapsed time between a request and its required response.')],relatedIds:['flight:01.01','flight:01.02','ground:power','ground:thermal','ground:data']});
topics.data=article('data',
 'A file-transfer test set follows data through the complete delivery path. It checks that payload input can be accepted, stored, recovered and returned without silently changing its contents. For a compute mission, that includes both ordinary job results and large artifacts such as model checkpoints.',
 P('The recorder, internal network, flight software and ground receiver contribute different pieces of the delivery contract. A capacity figure says how much can be stored, but not whether a file survives an interruption or arrives at the correct destination. A controlled test gives the file an identity and a known expected result before it enters the system.'),
 P('The test set can compare the original and returned bytes or their integrity checks, while the transfer software records progress and completion. Protocol behavior matters when contacts end before a file is complete. CCSDS CFDP defines file delivery for spacecraft and distinguishes acknowledged from unacknowledged operation; implementations such as Yamcs document how those services are exposed to operators.','cfdp','yamcs'),
 P('Transfer rate should be measured at the boundary the customer cares about. A fast electrical link may still produce slow file delivery after framing, retries, queueing and storage activity. Test files should exercise relevant sizes and storage states, and results should identify what portion of the path was real. A bench connection bypassing the radio cannot establish on-orbit contact availability.'),
 {suppliers:[supplier('Yamcs','CFDP service in the Yamcs ground system','A documented implementation example; protocol support and interoperability must be checked for a chosen mission.','yamcs'),supplier('Terma','Payload EGSE and instrument interfaces','An example of hardware and automation for exercising payload data interfaces.','terma-payload')],alternatives:[alternative('Raw link bit test','Measure error behavior of a defined digital stream.','Helps characterize the link, but does not prove storage and application-level delivery.'),alternative('End-to-end file test','Validate a named artifact through storage, transfer and the receiving application.','Adds software and queue behavior to the experiment and needs traceable test data.','cfdp')],inspection:['Trace the test set back to the recorder and payload network. These are distinct from the ground communications station used after launch.'],terms:[term('Checksum','A value computed from data to help detect unintended changes.'),term('Goodput','Useful application data delivered per unit time after overhead and retransmission.')],relatedIds:['flight:01.03','flight:01.04','ground:rf-ka','ground:rf-optical']});
topics.power=article('power',
 'The ground power cart supplies and tests the spacecraft while its solar arrays are unavailable or stowed. It can represent the electrical environment seen by the power-control system and observe how the battery and distribution equipment respond to a changing supply.',
 P('During integration, the spacecraft may need to operate for hours without exposing or illuminating its flight arrays. Ground equipment provides a controlled electrical source and measurement point. Its job includes the transition between external power, simulated solar input and battery operation; it is separate from the flight power-conditioning unit and does not contribute to the flight power budget.'),
 P('A normal programmable supply regulates a voltage or current. A solar-array simulator instead reproduces the source’s current–voltage behavior, which lets engineers exercise a maximum-power-point tracker and changing illumination. Electronic loads or battery emulators can represent other parts of the power path. Keysight’s application material explains these distinctions and the importance of the source’s dynamic response.','sas','battery-test'),
 P('Connections, remote-sense points, grounding and protection must match the interface under test. Cable voltage drop can otherwise make a stable cart output look like an unstable spacecraft bus. Testing also needs to distinguish peak demand from average demand and a brief transition from sustained eclipse energy use. The modeled cart illustrates this architecture; its enclosure size does not establish an electrical rating.'),
 {suppliers:[supplier('Keysight','Solar-array simulators and battery-test power equipment','Commercial examples for ground testing, with their own voltage, current and dynamic limits.','sas','battery-test'),supplier('Terma','Spacecraft EGSE power-test systems','An example of power testing integrated with central checkout.','terma-checkout')],alternatives:[alternative('Regulated bench supply','Power electronics at a fixed bus operating point.','Simple, but it does not reproduce a photovoltaic source curve.'),alternative('Solar-array simulator plus battery interface','Exercise source tracking and battery handover with repeatable profiles.','More representative, with additional configuration and calibration work.','sas')],inspection:['Separate the cart’s supply and sense/control paths from the spacecraft battery and PCDU.'],terms:[term('SAS','Solar-array simulator: equipment that reproduces an array’s electrical behavior.'),term('Remote sense','Measurement of voltage at the load to compensate for cable drop.')],relatedIds:['ground:power-converter','flight:02.01','flight:02.02','flight:02.03']});
topics.thermal=article('thermal',
 'A coolant service cart gives test hardware a temporary path for rejecting heat to the building. It can support powered checkout while flight radiators are stowed, covered or unable to reproduce their orbital environment. Ground conditioning is a test service with its own fluid and interfaces.',
 P('Every watt dissipated during a steady powered test must eventually leave the hardware. In the bay, that heat can pass through a temporary contact fixture or an agreed fluid interface to a ground cooler. The cart’s role must follow the spacecraft’s thermal architecture: a vehicle using passive heat pipes does not automatically acquire a flight coolant circuit just because a cart is present.'),
 P('A typical cart circulates process fluid through the test interface, measures supply and return temperatures, and transfers the heat to a facility loop or a refrigeration system. A reservoir accommodates inventory changes; a pump overcomes flow resistance. Boyd’s chiller manual provides a concrete example of these separate functions, while a plate heat exchanger can keep two fluid circuits apart.','chiller','phe'),
 P('The design must balance required heat removal, allowable interface temperature, pressure loss, fluid compatibility and cleanliness. Flow and temperature rise together help estimate transported heat; either reading alone is incomplete. Thermal vacuum testing later addresses a different boundary condition, because a successful room-temperature checkout does not reproduce heat exchange with the space environment.','gevs'),
 {suppliers:[supplier('Eaton Boyd Thermal','Recirculating chillers and liquid-cooling systems','Examples of terrestrial conditioning equipment; suitability for a spacecraft test interface is a separate engineering choice.','chiller','pump'),supplier('Alfa Laval','Plate heat exchangers','An example of equipment separating a clean process loop from another cooling circuit.','phe')],alternatives:[alternative('Facility-water heat exchanger','Reject heat to a building utility loop.','Requires an adequate facility supply and leaves a finite temperature difference across the exchanger.'),alternative('Self-contained refrigeration cart','Control process temperature independently of ordinary room air.','Adds electrical demand, compressor heat and maintenance.','chiller')],inspection:['Identify the pump, reservoir and heat exchanger as ground equipment; follow the linked spacecraft thermal pages for the flight heat path.'],terms:[term('Process loop','The fluid circuit serving the hardware being tested.'),term('Heat sink','The receiving environment or system to which heat is ultimately rejected.')],relatedIds:['ground:cooling-pump','ground:cooling-reservoir','ground:heat-exchanger','flight:03.01','flight:03.02']});
topics.attitude=article('attitude',
 'The attitude test bench checks whether the spacecraft correctly senses and responds to orientation. It can present a controlled optical or electrical scene to the flight system while the hardware remains supported on the ground. Testing knowledge of orientation and testing physical torque are different experiments.',
 P('A spacecraft needs a consistent relationship between its sensor axes, mechanical reference frame and actuator commands. A sign error or rotated mounting reference can produce a plausible numerical answer that commands the wrong direction. Ground testing therefore follows the chain from a known stimulus to the estimated attitude and then to the intended control response.'),
 P('A star-field stimulator presents a repeatable pattern to an optical sensor. The pattern can change as if the spacecraft were rotating, allowing the flight computer to process observations through its normal interface. Terma’s dynamic optical ground equipment is a real example. A separate simulation can close the loop by using commanded torque to update the next synthetic attitude.','star-stim','simulation'),
 P('A rigid stand prevents the spacecraft from responding physically to commanded torque. It is suitable for checking interfaces, timing and software logic, but a rotational test requires an appropriate motion fixture or a validated dynamics model. Optical alignment, room light, fixture flexibility and time synchronization all affect what the test actually demonstrates. Model inspection can show geometry without establishing sensor accuracy.'),
 {suppliers:[supplier('Terma','Dynamic Optical Ground Support Equipment','A documented star-tracker stimulus system; it is an example rather than the supplier of this schematic bench.','star-stim')],alternatives:[alternative('Electrical sensor emulation','Inject synthetic measurements after the sensor.','Efficient for control-software testing, but bypasses optics and sensor processing.'),alternative('Optical stimulation','Present a controlled sky to the actual optical head.','Includes more of the sensing chain and requires calibrated optical alignment.','star-stim')],inspection:['Identify the stimulus head and its shroud. The bench does not represent an unrestricted free-floating spacecraft.'],terms:[term('Attitude','The orientation of a body relative to a chosen reference frame.'),term('Hardware in the loop','A simulation that exchanges signals with real equipment.')],relatedIds:['flight:04.01','flight:04.02','flight:04.03','ground:alignment','ground:orbit']});
topics.propulsion=article('propulsion',
 'The propulsion service cart supports checkout of the spacecraft’s pressure and feed interfaces before operational propellant loading. It provides an instrumented ground boundary for engineering tests and keeps the supply equipment separate from the flight tanks, valves and engine installation.',
 P('A propulsion circuit has to preserve separation between different fluids, route each one to the intended destination, and remain within its verified pressure boundary. Ground checkout examines those interfaces with appropriate test equipment. It should not be confused with loading mission propellant: the dedicated servicing cell handles that different operation and its facilities.'),
 P('At a conceptual level, the cart connects a controlled source and calibrated measurements to selected service ports. Engineers compare the observed response with the approved circuit definition. Isolation, leakage and instrumentation can be examined without claiming that the model contains every valve or test instrument. NASA Kennedy describes specialist support for compatibility analysis, fluid conditioning and leak detection.','propellants'),
 P('The important design inputs are the test medium, pressure class, wetted-material compatibility, cleanliness, connection identification and measurement uncertainty. A visually similar fitting can belong to a completely different service. The cart’s hoses and instruments are explanatory geometry; test pressures, sequences and acceptance criteria come from the responsible propulsion and ground-system engineering teams.'),
 {suppliers:[supplier('Astrotech Space Operations','Propulsion pressure testing and servicing support','A real provider of spacecraft propellant and checkout services. No cart model or capacity has been selected here.','astrotech-prop'),supplier('NASA Kennedy','Propellants and Life Support capabilities','Institutional engineering and servicing reference, not a catalog cart manufacturer.','propellants')],alternatives:[alternative('Portable service cart','Bring a dedicated test interface to the article.','Flexible, with portable connections that require configuration control.'),alternative('Fixed facility test manifold','Keep instrumentation and supply infrastructure installed in one cell.','Reduces repeated setup but ties the operation to that facility.')],inspection:['Trace the distinct flight fuel, oxidizer and pressurant interfaces; the cart is ground support and is not launched.'],terms:[term('Wetted material','Any material that contacts the service fluid.'),term('Leak test','A defined measurement of unintended fluid escape across a pressure boundary.')],relatedIds:['ground:propellant-loading','flight:06.02','flight:06.03','flight:06.04','flight:06.05'],sourceIds:['gse']});
topics.mass=article('mass',
 'Weighing equipment measures the flight article that has actually been assembled. The result checks the mass ledger, while measurements at known support positions can also locate the center of gravity. Mass properties influence launch accommodation, attitude motion and the loads carried by handling fixtures.',
 P('The engineering model predicts mass from allocations; the scale measures the integrated hardware in a stated configuration. The two quantities only become comparable after removing fixture contributions and identifying what is installed, absent or still to be loaded. A spacecraft with shipping covers or uninstalled propellant is a different weighing configuration from the launch-ready article.'),
 P('Load cells measure forces at known locations. Their sum gives weight, and the distribution of those forces helps locate the center of gravity in the measurement plane. Measuring rotational inertia requires a different experiment. ESA’s physical-properties facilities explicitly distinguish weighing, center-of-gravity measurement, inertia measurement and balancing.','mass'),
 P('The fixture is part of the measuring system: deflection, leveling, tare and the relationship between spacecraft and instrument coordinates affect the result. Raptor Scientific discusses these practical issues for large spacecraft. A useful report includes uncertainty and configuration, not just a single mass. The workbench’s support shapes illustrate load paths; they are not calibrated instruments.','raptor'),
 {suppliers:[supplier('Raptor Scientific / Space Electronics','Weight, center-of-gravity and inertia instruments','A manufacturer of actual mass-properties equipment; the modeled pedestal load cells do not inherit a product rating.','raptor'),supplier('ESA ESTEC','Physical-properties test facilities','An example of a specialist measurement service.','mass')],alternatives:[alternative('Multiple calibrated support cells','Measure reactions at known support points.','Can reveal in-plane center of gravity; fixture geometry and tare matter.'),alternative('Dedicated mass-properties machine','Measure several properties using controlled orientations or motion.','More specialized equipment and handling are required.','mass')],inspection:['Look at the number and location of support points, then compare the flight article with the fixture beneath it.'],terms:[term('Tare','The contribution of the empty fixture removed from a measurement.'),term('Moment of inertia','Resistance to angular acceleration about a specified axis.')],relatedIds:['ground:checkout-stand','ground:lifting-yoke','flight:07.01','flight:09.01']});
topics.alignment=article('alignment',
 'The alignment station checks how actual attachment points and optical axes relate to the spacecraft’s reference frame. It turns a drawing’s coordinate system into measurable lines and targets on hardware, so parts fitted at different times can still point and mate as intended.',
 P('Mechanical fit and directional accuracy are related but different. A bracket can bolt into place while its instrument axis is slightly tilted; a set of supports can look symmetric while missing the intended datum. Alignment measurements connect those features to a common reference instead of relying on visual judgment or the edge of a nearby panel.'),
 P('An alignment telescope establishes a line of sight and observes targets or reference surfaces. Micrometers can resolve lateral departures from that line, while autocollimation methods measure angular alignment using a reflected reference. Brunson’s technical material and instrument data show what these functions mean in practical optical tooling.','brunson','brunson-learning'),
 P('The measurement plan selects datums that remain accessible as integration progresses. Fixture motion, thermal drift, target mounting and instrument calibration contribute to uncertainty. A laser tracker or photogrammetry system may be preferable for a large three-dimensional survey; a telescope remains useful when the required relationship is a line or angle. The drawing must state which relationship is being verified.'),
 {suppliers:[supplier('Brunson Instrument Company','Alignment telescopes and optical tooling','A real instrument family for understanding the station’s function; the rendered telescope is schematic.','brunson'),supplier('Beyond Gravity','Alignment tooling within system MGSE','An example of project-specific fixtures supporting spacecraft surveys.','mgse')],alternatives:[alternative('Line-of-sight optical tooling','Check straightness, offsets and angular relationships.','Requires suitable reference targets and clear sight lines.'),alternative('Three-dimensional metrology','Survey a network of points across the integrated article.','Adds coordinate fitting and uncertainty management; not every surface is a useful datum.')],inspection:['Follow the instrument’s line of sight toward a structural datum rather than assuming a decorative panel edge is the reference.'],terms:[term('Datum','A defined reference feature or frame used for dimensions and alignment.'),term('Autocollimation','Using reflected collimated light to measure angular alignment.')],relatedIds:['ground:alignment-telescope','flight:07.01','flight:05.03','ground:adapter']});
topics.fit=article('fit',
 'A fairing-clearance gauge helps inspect the space between the stowed spacecraft and its launch enclosure. The real requirement is a controlled usable envelope throughout the payload’s height, with allowance for motion and interfaces. The fairing’s outside diameter is not the available spacecraft diameter.',
 P('The tightest feature may be an antenna, radiator restraint, connector or upper corner where the fairing tapers. A clearance check therefore considers the whole stowed outline and its location relative to the separation plane. Payload guides explain accommodation using controlled envelopes and interface definitions, making them more useful than an exterior rocket dimension.','falcon','ariane'),
 P('A physical gauge can represent a limiting cross-section or interface boundary. Engineers can also compare a measured article with a digital envelope. Neither method should rely on a single camera angle: a feature hidden in one view may set the minimum clearance. The important measurement is the nearest approach in the relevant direction, with the correct reference plane and configuration.'),
 P('A stationary fit check addresses assembly geometry. Launch introduces deflection, vibration and relative movement, so the allowed volume must come from the provider’s mission interface definition. Access for mating and removal of temporary tooling also matters. The workbench gauge is an explanatory aid; the numerical fit screen does not replace a coupled structural or mission-specific accommodation assessment.'),
 {suppliers:[supplier('Launch provider','Controlled payload envelope and interface definition','SpaceX, Arianespace and ULA guides show different accommodation frameworks. The selected provider governs the actual mission.','falcon','ariane','vulcan'),supplier('Beyond Gravity','Custom test adapters and integration tooling','An example supplier of project-specific mechanical fixtures.','mgse')],alternatives:[alternative('Physical go/no-go gauge','Provide a tangible reference near a critical feature.','Easy to interpret locally, but may represent only part of the full envelope.'),alternative('Digital clearance survey','Compare measured or modeled geometry with the full allowed volume.','Depends on faithful configuration, registration and uncertainty.')],inspection:['Use side and end views to inspect taper, protrusions and the stowed deployment hardware.'],terms:[term('Dynamic envelope','The space reserved for an article including expected motion or deflection.'),term('Separation plane','The interface where the payload departs from its launch attachment.')],relatedIds:['launch:fairing','flight:09.01','flight:07.04','ground:adapter']});
topics.adapter=article('adapter',
 'The adapter inspection fixture makes the spacecraft-to-launcher interface accessible before final mating. It supports examination of the mounting plane, alignment features and connector access so that the flight adapter, separation system and spacecraft can be joined with a shared interface definition.',
 P('The launch adapter carries forces between two organizations’ hardware. Its fit therefore includes more than matching diameters: contact surfaces, locating features, fasteners, electrical break points and separation clearances all need compatible definitions. A fixture provides a repeatable physical reference for examining these relationships before the combined article is difficult to access.'),
 P('A representative interface can be used for a fit check, measurement or access rehearsal. The fixture supports the hardware through designated load paths while leaving critical features reachable. It may be a precision surrogate for a flight interface rather than flight hardware itself. Beyond Gravity’s adapter and integration-stand offerings show this family of purpose-built equipment.','mgse'),
 P('The supplier drawing and controlled interface document determine which dimensions matter. A fit-check article must state how closely it represents the final interface; wear, coatings and configuration changes can invalidate assumptions. Payload user guides provide the starting accommodation framework, while a mission agreement closes the particular interface. A successful visual fit alone cannot establish separation performance.','falcon','vulcan'),
 {suppliers:[supplier('Beyond Gravity','Spacecraft test and handling adapters','An example of custom ground adapters; the flight separation system is a different article.','mgse'),supplier('Launch provider','Flight interface and mission accommodation data','The selected provider and spacecraft team jointly resolve the actual interface.','falcon','vulcan')],alternatives:[alternative('Flight-hardware fit check','Mate the actual controlled interface articles.','Representative, but exposes valuable hardware to handling and schedule constraints.'),alternative('Qualified interface surrogate','Use a verified replica for access and alignment work.','Requires traceability to the current flight drawing and its tolerances.')],inspection:['Distinguish the ground stand from the flight adapter and separation plane; only the latter are part of the launched interface.'],terms:[term('Interface control document','The agreed definition of how independently developed systems connect.'),term('Fit-check article','Hardware used to verify geometric compatibility.')],relatedIds:['ground:adapter-stand','flight:09.01','launch:vehicle']});
topics.environment=article('environment',
 'The cleanroom monitor measures the environment around exposed spacecraft hardware. Its particle counter helps reveal changes in airborne contamination, while the overall monitoring plan may also track temperature, humidity and deposited contamination on witness samples.',
 P('Cleanliness preserves function. Dust on optics scatters light; contaminants on thermal or electrical surfaces can change their behavior. The relevant environment is the region around the work, which may differ from a remote room sensor. NASA’s cleanroom introduction discusses the importance of controlling contamination through integration and transport.','clean'),
 P('An airborne particle counter samples a known air volume and sorts detected events into size ranges. A portable instrument can investigate a local operation; fixed sensors can show changes over time. Particle Measuring Systems offers both approaches. Airborne counts do not directly tell how much material has deposited on a particular mirror or radiator, so surface monitoring answers a complementary question.','pms'),
 P('The monitoring plan should connect each measurement to a sensitive item or operation. Sensor location, sampling interval, calibration, work activity and protective covers affect interpretation. Cleanroom class is a statement about a defined environment and measurement method, not a guarantee that every component is clean. Molecular films can matter even when particle counts look satisfactory.'),
 {suppliers:[supplier('Particle Measuring Systems','Portable and fixed contamination monitors','Examples include Lasair and IsoAir instruments; no instrument accuracy or cleanliness class is assigned to this schematic monitor.','pms')],alternatives:[alternative('Portable sampling','Move an instrument near the current work area.','Good for local investigation but provides incomplete coverage when moved elsewhere.'),alternative('Fixed monitoring plus witness samples','Track environmental trends and material reaching selected surfaces.','Needs a planned sensor network and a separate interpretation of airborne versus deposited contamination.')],inspection:['Locate the sampling area relative to exposed flight hardware. The display represents monitoring equipment, not a measured cleanliness result.'],terms:[term('Witness sample','A representative surface exposed alongside hardware to assess contamination.'),term('Molecular contamination','Thin films or residues that are not counted simply as airborne dust particles.')],relatedIds:['ground:facility','ground:gse-storage','flight:03.03','flight:05.03']});
topics.orbit=article('orbit',
 'The orbit simulator lets flight software experience a changing mission environment while the spacecraft remains in the building. It supplies time-dependent conditions such as position, illumination, sensor observations or communications opportunities through the test interfaces selected for that experiment.',
 P('The purpose is to test behavior over time: what the vehicle does at separation, eclipse entry, a scheduled activity or a contact transition. Accelerating a model can make a long mission scenario easier to inspect, but timing-dependent hardware may require real-time execution. The test must state which clock drives the flight system and which environment signals are being emulated.'),
 P('A model advances the trajectory and environment, then converts that state into the inputs expected by the equipment under test. The spacecraft produces commands and telemetry in return. NASA Johnson’s simulation capabilities illustrate connecting flight-like systems to modeled surroundings; an RF navigation simulator is a more specialized tool that can stimulate a real GNSS receiver rather than bypassing it.','simulation','gnss-sim'),
 P('Different test boundaries answer different questions. Feeding a position directly to software checks downstream logic; feeding synthetic radio signals also exercises the receiver. A plausible animated orbit is not sufficient evidence that either interface is correct. Coordinate frames, time standards, update rates and latency must be agreed between the simulator and flight system.'),
 {suppliers:[supplier('Spirent','GNSS constellation simulators','An example of RF navigation-signal simulation; the linked historical datasheet is not a current product selection.','gnss-sim'),supplier('Terma','Spacecraft simulators and processor emulation','Examples of operational and software-validation environments.','terma-checkout')],alternatives:[alternative('Software-only simulation','Run the controller and mission environment as software.','Fast and repeatable, with fidelity limited by the modeled hardware.'),alternative('Hardware-in-the-loop simulation','Connect representative electronics through real interfaces.','Exercises timing and interfaces but requires calibrated test hardware and synchronized execution.')],inspection:['The rack represents a source of simulated conditions; it does not move the spacecraft or recreate vacuum.'],terms:[term('Ephemeris','A time-indexed description of an object’s position and motion.'),term('Real-time simulation','A model that progresses at the same rate as the connected physical system.')],relatedIds:['ground:checkout','ground:attitude','flight:08.01','flight:04.03']});
topics.avionics=article('avionics',
 'The spacecraft command console is the ground operator’s interface to the flight computer. It sends controlled requests, decodes returned status and records what happened. This establishes the command path that keeps the vehicle understandable and operable independently of its customer compute payload.',
 P('A data-center accelerator can be idle while the spacecraft computer remains responsible for power, temperatures, communications and the mission sequence. The console therefore tests the housekeeping path as well as any payload commands routed through it. The key question is whether a command reached the intended function and produced the expected state, not merely whether a cable carried bytes.'),
 P('Commands are encoded using an agreed definition, passed through a test interface and interpreted by the flight software. Returned telemetry is decoded with the matching database and linked to a timestamp. Central checkout software can automate these exchanges and retain their history; NASA’s ground-system survey describes the continuity between development, integration tests and operations.','terma-checkout','ground-ground-data'),
 P('Software versions, command definitions, units and timestamps are part of the test configuration. A stale database may misinterpret healthy telemetry, while a direct debug connection may bypass the normal command route. Procedures should record those boundaries so that a successful bench exchange is not mistaken for a demonstrated end-to-end flight communications service.'),
 {suppliers:[supplier('Terma','CCS5 central checkout and operations software','A real example of shared test and operations tooling.','terma-checkout'),supplier('Yamcs','Mission-control and file-transfer services','An example of documented ground software; the workbench does not install a mission-control system.','yamcs')],alternatives:[alternative('Direct engineering interface','Access the flight computer through a local debug or maintenance port.','Useful during development, but may bypass the operational command chain.'),alternative('Operational command route','Use the intended packet, modem and spacecraft interfaces.','More representative, requiring compatible ground and flight configurations.')],inspection:['Compare the ground console with the linked flight avionics enclosure; they have different roles and mass boundaries.'],terms:[term('Command database','The definition of command identifiers, parameters and encoding.'),term('Housekeeping telemetry','Status describing the spacecraft’s health and operating state.')],relatedIds:['flight:08.01','ground:checkout','ground:rf','ground:orbit']});

topics.rf=article('rf',
 'The command and telemetry rack tests the spacecraft’s radio control link while the vehicle is still accessible on the ground. It connects the command software to RF instruments and a controlled spacecraft interface, allowing engineers to distinguish a radio problem from a packet, software or wiring problem.',
 P('A healthy flight computer is useful only if operators can reach it. This station exercises the path between encoded commands, the receiver, onboard interpretation and returned telemetry. Ground checkout usually uses a controlled short path instead of the actual space-to-ground link, so the test plan must say which antennas, cables and electronics are included.'),
 P('A representative chain includes a modem, frequency conversion, controlled attenuation, measurement instruments and an RF connection to the spacecraft. The receiver is stimulated with a known signal and the returned transmission is examined. Terma’s TT&C brochure provides a useful block diagram of this type of special checkout equipment; its instruments support several bands rather than defining this particular spacecraft’s link.','rf-brochure'),
 P('Frequency alone does not establish compatibility. Modulation, coding, signal level, timing and command formats must match. A conducted connection can isolate electronics, while a nearby antenna or coupler can include more of the installed RF path. Cable loss and coupler behavior must be known to interpret measurements. A functional exchange in a room does not demonstrate flight antenna gain or mission link margin.'),
 {suppliers:[supplier('Terma','RF SCOE and TT&C test systems','A documented supplier of spacecraft radio test equipment. The modeled rack is not identified as a particular Terma installation.','rf-scoe')],alternatives:[alternative('Conducted RF test','Connect through a specified cable or test port.','Repeatable and useful for fault isolation, but excludes some antenna behavior.'),alternative('Radiated or coupled test','Exchange signals through installed antenna hardware.','Includes more of the end-to-end path, while the test geometry requires careful interpretation.')],inspection:['Follow the station-to-antenna test path and distinguish the external rack from the flight transceiver.'],terms:[term('TT&C','Telemetry, tracking and command: the communications needed to monitor and control a spacecraft.'),term('Attenuation','A controlled reduction of signal power.')],relatedIds:['ground:rf-test-hat','ground:avionics','flight:05.01']});
topics['rf-ka']=article('rf-ka',
 'The Ka-band receiver and bit comparator test the high-rate payload data path. A receiver reconstructs the transmitted bitstream; a comparator checks it against a known pattern or expected content. This provides evidence about data integrity rather than merely showing that RF power is present.',
 P('The useful output of a data-center satellite is delivered information. Errors, missing packets, decoder losses and interrupted timing can reduce that output even if the transmitter turns on successfully. The station links the flight modem and RF chain to a measurable ground result, complementing the software-level file and workload tests.'),
 P('A test source supplies a reproducible pattern, or the payload sends a known file. The ground receiver follows the agreed waveform and reconstructs the output. Measurements can examine bit errors, synchronization and recovery after a controlled interruption. Terma’s RF checkout family is an example of equipment integrating instruments and automated measurements across bands including Ka.','rf-scoe'),
 P('Raw bit rate, decoded data rate and useful file delivery rate are different quantities. A test should identify its boundary and observation duration, particularly when an error rate is low. The test port and installed antenna also represent different boundaries. High-rate digital processing, cable behavior and RF calibration all affect interpretation; a benchtop result does not include rain attenuation, a moving ground station or the complete orbital link budget.'),
 {suppliers:[supplier('Terma','Automated spacecraft RF test equipment','An example of integrated receiver, converter and measurement functions; no modem, operating frequency or performance rating is assigned here.','rf-scoe','rf-brochure')],alternatives:[alternative('Known-pattern bit-error test','Compare recovered bits against a deterministic reference.','Provides a focused physical-link measurement but may omit file handling and application behavior.'),alternative('End-to-end file delivery test','Transfer representative payload products and verify their integrity.','Exercises more of the mission chain, but diagnosis requires measurements at intermediate layers.','cfdp')],inspection:['The rack is a ground receiver and measurement system. Its displayed geometry does not represent the flight antenna aperture.'],terms:[term('Bit-error ratio','The number of incorrect recovered bits divided by the number examined.'),term('Goodput','Useful application data delivered per unit time, excluding protocol overhead and retransmissions.')],relatedIds:['ground:ka-test-port','ground:data','flight:05.02']});
topics['rf-optical']=article('rf-optical',
 'The optical alignment bench checks how a laser communications terminal points, receives and exchanges test signals. Optical communication needs both a working data chain and accurate overlap between a narrow transmitted beam, the intended target and the terminal’s tracking reference.',
 P('Electrical checkout cannot show that a beam leaves in the intended direction. The bench provides a stable reference for relating the terminal’s optical axis, tracking sensor and mounting datums. It can also supply a controlled optical target or receiver. The precise test boundary depends on whether the terminal is a complete integrated unit or separate telescope, modem and pointing assembly.'),
 P('Reference optics form or collect a beam with a known relationship to the bench. Detectors and metrology then compare the terminal response with that reference. NASA’s TBIRD preflight paper illustrates why alignment stability and pointing feedback belong in an optical communications verification campaign. Safran and Jena-Optronik publish examples of the specialized optics used for spacecraft testing.','tbird','ogse','jena'),
 P('Boresight alignment, wavefront quality, received power and data integrity are related but distinct measurements. Bench motion, temperature, optical cleanliness and reference-frame registration can masquerade as terminal errors. A short indoor optical path does not reproduce atmospheric turbulence or a long-range pointing problem. Test documentation therefore needs to say what is measured directly and what remains an analysis or later field demonstration.'),
 {suppliers:[supplier('Safran Reosc','Optical ground support equipment','Examples of precision optical test and calibration systems.','ogse'),supplier('Jena-Optronik','Optical ground support equipment and metrology','An example of reference optics and alignment services; not a selected vendor for this workbench.','jena')],alternatives:[alternative('Internal optical loopback','Exercise the terminal’s electronics and portions of its optical path locally.','Efficient for functional checks but may bypass external pointing and beam quality.'),alternative('External reference bench','Measure the terminal against independent optics and detectors.','Adds alignment and environmental requirements but includes more of the assembled optical interface.')],inspection:['Look for the relationship between the flight aperture and the separate test head. A visible beam is an explanatory overlay, not a measured propagation result.'],terms:[term('Boresight','The defined pointing axis of an optical or radio instrument.'),term('Collimator','Optics that produce or receive a nearly parallel bundle of rays.')],relatedIds:['ground:optical-test-head','ground:alignment','flight:05.03']});
topics['propellant-loading']=article('propellant-loading',
 'The dedicated servicing cell represents the facility, interfaces and support equipment used when a spacecraft receives its mission propellant. It is distinct from an ordinary functional checkout station because fluid compatibility, contamination control and the state of the loaded spacecraft become central parts of the campaign.',
 P('Different spacecraft propulsion systems use very different fluids, storage states and servicing arrangements. A room that supports one architecture is not automatically suitable for another. The selected design’s propellant and processing assumptions must therefore govern the facility assessment, rather than a generic image of a fueling cart. NASA Kennedy describes servicing as an engineering capability involving analysis, equipment and infrastructure.','propellants'),
 P('At a system level, servicing connects an external fluid supply and measurement system to the spacecraft’s approved interface. The spacecraft changes from an unloaded article to a controlled loaded configuration, and that configuration affects subsequent handling and testing. The physical cell also provides separation from incompatible work and access to the equipment needed for the particular campaign. Astrotech documents commercial spacecraft propellant services and related test support.','astrotech-prop'),
 P('Key design questions concern compatible wetted materials, cleanliness, inventory accounting, access to the service connection and the ground-to-flight pressure boundary. The load cannot be inferred from the size of the rendered vessel. This article explains the system role; actual media, limits and execution belong to the responsible provider’s approved servicing documentation, not the workbench animation.'),
 {suppliers:[supplier('Astrotech Space Operations','Spacecraft propellant services','A real processing-service example; capability for a particular spacecraft must be established with the provider.','astrotech-prop'),supplier('NASA Kennedy','Propellant handling and servicing capabilities','An institutional reference for the supporting engineering disciplines.','propellants')],alternatives:[alternative('Dedicated processing cell','Conduct servicing in an established facility adapted for the selected mission.','Can separate activities and centralize infrastructure, with additional transfer and scheduling interfaces.'),alternative('Mission-specific servicing equipment','Bring compatible equipment into an approved processing arrangement.','Offers flexibility but does not remove facility, configuration or interface requirements.')],inspection:['The cell is a ground operation boundary. The spacecraft’s tanks remain separate flight parts with their own inventories.'],terms:[term('Wetted materials','Materials that contact the working fluid.'),term('Loaded configuration','The documented hardware and fluid state after servicing.')],relatedIds:['ground:propulsion','ground:facility','flight:06.03','flight:06.04','flight:06.06','flight:06.07']});

topics['checkout-stand']=article('checkout-stand',
 'The spacecraft checkout stand supports the vehicle at a defined mechanical interface while integration and functional tests are performed. Its useful features are stable load paths, repeatable alignment and access around the article, rather than resemblance to a generic workshop table.',
 P('Flight hardware often cannot rest directly on a floor. Appendages, connectors and delicate surfaces need clearance, and the spacecraft structure expects loads to enter through selected hard points. The stand transfers those loads into the building while keeping service connections and inspection areas reachable. It also establishes the reference configuration used when several stations test the same spacecraft.'),
 P('An adapter mates the spacecraft to a supporting structure. The structure distributes load through its legs or base, and may provide controlled orientation or transport functions if those functions are part of its actual design. Beyond Gravity’s integration stands and multipurpose trolleys illustrate different combinations of support, access and reorientation. The model shows a support concept, not a demonstrated mechanism or certified load capacity.','mgse','trolley'),
 P('The center of gravity, support footprint and interface stiffness affect stability and measurement quality. Cable and hose forces should not become unintended structural restraints. Access openings must be considered along with strength, and a stand suitable for static checkout may not be suitable for transport, lifting or a structural test. NASA’s GSE standard is a useful starting reference for documenting a purpose-built support article.','gse'),
 {suppliers:[supplier('Beyond Gravity','Spacecraft integration stands and handling trolleys','Examples of custom mechanical ground support equipment; the rendered stand has no assigned manufacturer.','mgse','trolley')],alternatives:[alternative('Fixed support stand','Hold one controlled spacecraft orientation.','Mechanically simple but may require additional equipment to access other faces.'),alternative('Tilting or rotating fixture','Present different faces to personnel and instruments.','Improves access while adding motion, restraint and configuration-management requirements.')],inspection:['Find where the stand meets the flight structure and where its load enters the floor. Check that the support does not pass through a deployed appendage.'],terms:[term('Hard point','A structural feature intended to accept a defined load or attachment.'),term('Support footprint','The area bounded by the stand’s floor contact points.')],relatedIds:['ground:facility','ground:checkout','ground:adapter-stand','flight:07.01','flight:09.01']});
topics['adapter-stand']=article('adapter-stand',
 'The adapter stand holds the spacecraft’s launch-interface hardware in an accessible ground configuration. It lets engineers inspect, measure and prepare the adapter without treating its thin edges, connectors or separation features as convenient floor supports.',
 P('An adapter has two jobs in the wider system: transmitting launch loads and establishing a separable interface between the vehicle and payload. During ground preparation it also needs a defined support condition. A dedicated stand keeps reference surfaces accessible and helps preserve their relationship to measurement equipment, handling fixtures and eventual mating hardware.'),
 P('The stand supports selected features of the adapter through pads or a representative interface, then carries that load to its base. Its geometry can provide clearance beneath a ring and working space around the separation plane. Custom test adapters and integration stands are established MGSE product families; they are different from the flight adapter itself.','mgse'),
 P('The ground support condition should match the task. A fit inspection, a mass-properties measurement and a structural test may require different fixtures even when all involve the same adapter. The interface definition should identify contact surfaces, prohibited contact zones and alignment references. Some workbench launcher layouts have no separate adapter stand; the educational topic still explains the allocation while the model states its availability.'),
 {suppliers:[supplier('Beyond Gravity','Test adapters and integration stands','A supplier example for dedicated interface tooling. No flight separation-system selection follows from this example.','mgse'),supplier('Launch provider','Payload interface definition','Provider guides explain accommodation and launch-interface responsibilities; mission-specific documents resolve actual details.','falcon','ariane','vulcan')],alternatives:[alternative('Dedicated adapter fixture','Optimize support and access for one interface family.','Requires a controlled configuration for each adapter variant.'),alternative('Configurable interface stand','Use interchangeable adapters on a common base.','Reduces duplicate equipment while adding changeover and configuration checks.')],inspection:['Separate the support stand, flight adapter and any surrounding inspection gauge in the model hierarchy. Their names may refer to the same interface but different hardware.'],terms:[term('Mating surface','A controlled surface that contacts or aligns with another assembly.'),term('Ground adapter','A fixture interface that connects flight hardware to non-flight support equipment.')],relatedIds:['ground:adapter','ground:checkout-stand','flight:09.01']});
topics['bridge-crane']=article('bridge-crane',
 'The overhead bridge crane moves suspended flight hardware across the integration area. Its bridge establishes travel along the building, a trolley establishes travel across the bridge, and a hoist provides vertical motion. Together they position a suspended load without requiring it to roll across the floor.',
 P('Spacecraft assembly often involves moving an article from a receiving cradle to a stand or launch interface. The crane provides the large-scale motion, while the lifting yoke and frame connect that motion to approved spacecraft pickup points. The building structure, crane and below-hook tooling form one load path, even though different teams may supply them.'),
 P('Loads pass from the hook through the hoist and trolley into bridge girders, runway supports and the building. Motion of a suspended article also introduces sway and changes the required clearance. American Crane’s Kennedy Space Center case study is a real example of adapting overhead handling equipment to spacecraft cleanroom work.','crane'),
 P('Capacity is only one design consideration. Required travel, hook height, positioning control, structural deflection, contamination control and recovery from an interrupted movement all affect suitability. A visible animation demonstrates intended sequence and clearance only; it does not calculate suspended-load dynamics or establish a certified lift. NASA’s GSE standard provides a broader framework for purpose-built ground equipment documentation.','gse'),
 {suppliers:[supplier('American Crane & Equipment Corporation','Cleanroom overhead crane systems','The linked Kennedy case study demonstrates the application class, not the manufacturer or rating of this schematic crane.','crane')],alternatives:[alternative('Building-mounted bridge crane','Cover a substantial integration work area from overhead.','Requires compatible building structure and an unobstructed travel envelope.'),alternative('Dedicated gantry or lifting fixture','Place the lifting function around one operation.','Can localize infrastructure but may constrain access and usable floor space.')],inspection:['Trace the load from the spacecraft through yoke, hook, trolley and bridge. Examine the required clearances at both ends of the move.'],terms:[term('Runway','The supporting track along which a bridge crane travels.'),term('Below-hook tooling','The specialized lifting equipment between the crane hook and the lifted article.')],relatedIds:['ground:crane-hoist','ground:lifting-yoke','ground:lifting-frame','ground:receiving-cradle','ground:checkout-stand']});
topics['crane-hoist']=article('crane-hoist',
 'The crane hoist provides controlled vertical movement between the bridge-crane trolley and its hook. It is the lifting actuator in the handling chain, while the yoke and spacecraft attachments determine how that force reaches the payload.',
 P('A bridge crane can place a hook over an article, but the hoist must raise, hold and lower the complete suspended assembly. That assembly includes the flight hardware and all lifting tooling. Hoist travel and available headroom can therefore limit an integration operation even when the building appears tall enough in a wide view.'),
 P('A hoist converts actuator motion into controlled motion of a rope or chain and hook assembly. The actual implementation determines its braking, reeving and load-monitoring arrangements. Those internals are not resolved by this schematic model. The American Crane cleanroom example shows why spacecraft handling is an application-specific system rather than an arbitrary industrial hoist placed above valuable hardware.','crane'),
 P('Positioning precision, minimum controllable movement and the ability to retain a suspended load are separate from nominal capacity. The hook, connection hardware and below-hook tooling must also have compatible geometry. A change to the lifting frame changes the total suspended mass and may change headroom. The handling plan should refer to the controlled equipment configuration, not to a visual estimate of the spacecraft alone.','gse'),
 {suppliers:[supplier('American Crane & Equipment Corporation','Spacecraft-processing crane and hoist systems','A real application example; no hoist mechanism, brake architecture or rated capacity is assigned to this rendering.','crane')],alternatives:[alternative('Single central hoist with a spreader','Introduce one suspended load path and distribute it below the hook.','Simple at the crane interface but requires suitable below-hook tooling.'),alternative('Purpose-built synchronized lifting system','Control multiple support points as one handling operation.','Can address specialized geometry while introducing synchronization and load-sharing requirements.')],inspection:['Look at hook height and the space occupied by the yoke before judging whether the spacecraft can clear its stand.'],terms:[term('Headroom','The vertical space consumed by lifting equipment above the article.'),term('Reeving','The arrangement of rope through sheaves that establishes a hoist’s mechanical advantage and travel.')],relatedIds:['ground:bridge-crane','ground:lifting-yoke','ground:lifting-frame']});
topics['lifting-yoke']=article('lifting-yoke',
 'The lifting yoke connects the crane hook to a wider set of pickup points. It spreads or redirects the suspended load so the spacecraft can be handled through intended structural attachments instead of squeezing delicate hardware toward a single hook.',
 P('An article with several lifting points cannot be understood as a single mass hung from an arbitrary corner. Its center of gravity determines the suspended attitude, while the pickup geometry determines how force is shared. The yoke helps establish that geometry and can preserve clearance around protrusions, thermal surfaces and stowed appendages.'),
 P('The hook loads the yoke at one or more top connections. The yoke then transfers force through its structure to lower attachments and onward to a lifting frame or flight hard points. Depending on geometry, members may carry tension, compression and bending. Beyond Gravity lists spacecraft lifting devices among its system MGSE offerings, illustrating this custom-tooling role.','mgse'),
 P('A useful design definition includes pickup locations, permitted orientations, mass and center-of-gravity range, attachment compatibility and access for connection. Changing the spacecraft configuration can change load distribution even when total mass barely changes. A rigid-looking rendered bar is not evidence of stiffness, allowable load or proof testing. Those properties require an engineered and documented ground tool.','gse'),
 {suppliers:[supplier('Beyond Gravity','Spacecraft lifting devices','An example of the supplier category. The modeled yoke is explanatory geometry with no assigned certified rating.','mgse')],alternatives:[alternative('Rigid lifting beam or yoke','Maintain defined spacing between pickup points.','Adds tooling mass and headroom but can protect the article from unwanted lateral loads.'),alternative('Engineered sling arrangement','Use flexible members between a hook and designated lifting points.','Compact to store, with load distribution and clearance sensitive to geometry and suspended attitude.')],inspection:['Follow each lower connection to a structural pickup point. The outer skin and solar-array edges are not implied lifting surfaces.'],terms:[term('Pickup point','A designated attachment through which an article may be lifted.'),term('Load sharing','How total force divides among several supports or attachments.')],relatedIds:['ground:bridge-crane','ground:crane-hoist','ground:lifting-frame','flight:07.01']});
topics['lifting-frame']=article('lifting-frame',
 'The spacecraft lifting frame is the local structure that joins multiple approved pickup points into one controlled handling interface. It keeps the lifting tool’s geometry separate from the flight structure and allows the crane connection to sit clear of sensitive equipment.',
 P('The spacecraft may need to be moved while antennas, radiators or arrays are folded around its body. A frame provides a route for lifting loads that avoids those surfaces and preserves access to structural hard points. It can also establish a repeatable suspended orientation for installation into a larger assembly.'),
 P('The frame accepts force from the yoke or hoist and distributes it to its attachment locations. Its rigidity and the attachment geometry influence how those loads share. Some real fixtures include adjustable or interchangeable interfaces, but those features must not be inferred from a schematic model. Custom lifting devices and integration adapters are documented MGSE offerings.','mgse'),
 P('The interface must be assessed as a complete assembly: frame, connection hardware, spacecraft attachments and suspended configuration. Clearance during attachment and removal matters just as much as clearance during travel. Handling points suitable for one orientation may not be appropriate after a major rotation. A workbench sequence can help inspect geometry and order of operations; it does not verify the frame’s structural performance.','gse'),
 {suppliers:[supplier('Beyond Gravity','Custom spacecraft lifting and handling tooling','A real supplier example for this equipment class; the workbench frame is not a vendor drawing.','mgse')],alternatives:[alternative('Dedicated lifting frame','Design the tooling around one spacecraft geometry and pickup arrangement.','Offers tailored clearance with limited reuse across different configurations.'),alternative('Modular lifting tooling','Use controlled interchangeable interfaces on a common structure.','Can support a product family, with added attention to configuration and incorrect assembly prevention.')],inspection:['Compare the frame’s attachments with the vehicle’s structural load path. Check whether the tool can be removed after the next mating operation.'],terms:[term('Handling interface','The mechanical connection and constraints used to support or move an article on the ground.'),term('Tooling envelope','The space occupied by a tool throughout installation, use and removal.')],relatedIds:['ground:lifting-yoke','ground:checkout-stand','ground:cargo-load-bridge','flight:07.01']});
topics['receiving-cradle']=article('receiving-cradle',
 'The receiving support holds the launch-stage or carrier assembly as it enters the integration workflow. Depending on the launcher, the model represents a horizontal upper-stage cradle, a Starship transport support or a vertical launch interface. Each provides a controlled resting configuration for subsequent access and mating.',
 P('A transport container, receiving support and spacecraft checkout stand solve different problems. This receiving support accepts the carrier-side article, leaving vulnerable surfaces clear of the floor and making the payload integration interface accessible. Its exact orientation follows the selected launcher. The actual load-bearing contacts matter more than whether the equipment resembles a table or a cradle.'),
 P('The cradle transfers weight from designated support areas to a stable base. Shaped supports may locate a cylindrical or irregular article, while adapters can connect to hard points. Restraints for transport and supports for stationary work are different functions and should be defined separately. Beyond Gravity’s handling trolleys illustrate the broader family of support equipment used between spacecraft operations.','trolley'),
 P('Support location, local contact pressure, center-of-gravity range and access for the next tool all influence the design. Cleanliness protection remains relevant near exposed payload interfaces while covers are removed and connections are inspected. NASA’s cleanroom introduction is useful context for why receipt and staging remain controlled integration activities.','clean'),
 {suppliers:[supplier('Beyond Gravity','Custom handling and support equipment','An example of the broader MGSE equipment class, not an identified supplier of this launcher-side support.','trolley','mgse')],alternatives:[alternative('Dedicated receiving cradle','Provide a stable configuration optimized for receipt and inspection.','Adds a transfer before the article reaches its next support.'),alternative('Combined transport and integration support','Keep the article on one compatible fixture through several activities.','Reduces transfers but requires one structure to satisfy several access and restraint needs.')],inspection:['Identify whether the selected layout supports a horizontal stage or a vertical carrier. A nearby platform may support people or tools rather than flight hardware.'],terms:[term('Cradle','A support that locates an article through shaped or arranged contact points.'),term('Staging','Holding an article in a controlled configuration between operations.')],relatedIds:['ground:facility','launch:upper','launch:vehicle','ground:transfer-support','ground:environment']});
topics['gse-storage']=article('gse-storage',
 'Ground-equipment storage preserves tools, test adapters, cables and protective hardware between operations. For spacecraft work, a useful storage system also preserves identity, configuration and cleanliness so that the correct article can be returned to service without ambiguity.',
 P('A missing adapter or an unidentified cable can interrupt a campaign as effectively as a failed instrument. Storage connects the physical tool to its drawing revision, applicable interfaces and maintenance or calibration record. Protective covers and organized locations also reduce unnecessary handling of precision surfaces and connectors.'),
 P('Equipment is grouped by its function and condition, with packaging appropriate to the item. A precision optical reference, a mechanical lifting fixture and an electrical lead do not have identical storage needs. NASA’s GSE standard provides a system-level reference for ground equipment documentation, while contamination-control guidance explains why clean tooling must stay protected outside the immediate work area.','gse','clean'),
 P('Storage design should consider retrieval clearance, support at intended contact points and separation of incompatible items. It should be possible to tell whether an article is available for use, awaiting inspection or configured for a different vehicle. The rendered racks represent a support allocation rather than an inventory database; the workbench does not infer calibration status or readiness from an item’s presence on a shelf.'),
 {suppliers:[supplier('Payload-processing provider','Controlled tooling and support areas','Astrotech’s processing facilities illustrate the broader services around cleanroom work; specific storage arrangements remain mission-dependent.','astrotech')],alternatives:[alternative('Dedicated project storage','Keep one spacecraft’s tools and interfaces together.','Easy to identify, with greater space demand and potentially duplicated equipment.'),alternative('Shared equipment pool','Reuse controlled ground equipment across projects.','Can improve utilization, while increasing scheduling and configuration-management responsibilities.')],inspection:['The rack is ground infrastructure. Stored tools do not add to flight mass merely because they are visible beside the spacecraft.'],terms:[term('Configuration identification','Knowing which controlled version and arrangement of an item is present.'),term('Calibration status','The documented relationship between a measurement instrument and its reference checks.')],relatedIds:['ground:facility','ground:environment','ground:alignment','ground:lifting-frame']});
topics['fairing-carrier']=article('fairing-carrier',
 'A fairing-half carrier supports one protective shell section while it is stored, moved or positioned around the payload. The shell’s large area and relatively thin construction make its support geometry more important than its apparent bulk might suggest.',
 P('A fairing protects the payload during atmospheric ascent, but on the ground it must be handled without distorting mating edges, damaging acoustic treatments or contaminating the payload volume. A dedicated carrier keeps the half shell stable and leaves its joining surfaces accessible. It is separate from the launch fairing and remains on the ground.'),
 P('The carrier introduces loads at intended support locations and transfers them into a base or transport mechanism. Multiple contacts can locate the shell, but their geometry must avoid unintended forced fit. The three-point arrangement visible in the workbench is an explanatory support concept; it is not a published provider fixture or a calculated load distribution. Custom panel-handling equipment is an established MGSE category.','mgse'),
 P('Fairing geometry, center of gravity, edge clearances, contact protection and the intended mating sequence drive the carrier design. The selected provider’s integration method matters: a split expendable fairing and an integrated cargo bay have different handling needs. Payload manuals show how enclosure and processing arrangements vary between launch services, so one carrier should not be generalized to every vehicle.','falcon','ariane'),
 {suppliers:[supplier('Launch provider and its MGSE suppliers','Fairing-specific handling fixtures','The actual fixture is provider-controlled. Beyond Gravity is an example supplier of custom panel and spacecraft handling equipment, not an identified maker of this carrier.','mgse')],alternatives:[alternative('Dedicated half-shell carrier','Support and present an individual fairing section.','Requires fixture geometry matched to that shell and mating sequence.'),alternative('Integrated enclosure handling','Move or assemble a larger enclosure unit as part of provider processing.','Changes access, lifting and facility needs; not interchangeable with a half-shell procedure.')],inspection:['Inspect support contacts and clearance around the fairing edges. The rendered carrier is not flight equipment.'],terms:[term('Fairing half','One shell section of a separable payload enclosure.'),term('Kinematic support','A support arrangement intended to locate an article without redundant geometric constraint.')],relatedIds:['launch:fairing','ground:fit','ground:transfer-support','ground:facility']});
topics['transfer-support']=article('transfer-support',
 'The payload transfer support carries the integrated article between preparation and launch-vehicle mating positions. It preserves a controlled mechanical interface while the surrounding equipment and load path change.',
 P('Integration is a sequence of handoffs: receiving support, checkout stand, lifting fixture, transport support and launch adapter. Each handoff must leave the article supported through intended structure. The transfer support belongs to that chain and can also keep service connections accessible until their removal is required by the mission sequence.'),
 P('The support combines an interface to the payload or adapter with a base suited to the selected transfer arrangement. It may be transported as an assembly or used as a stationary intermediate support; the workbench animation indicates the intended geometric sequence rather than prescribing a real movement method. Beyond Gravity’s MGSE examples show why these interfaces are generally tailored to the spacecraft and facility.','mgse','trolley'),
 P('The important questions are where the load enters, which support is active at each stage, what clearances are required and how the tool is removed after mating. Center-of-gravity changes and retained tooling need explicit treatment. Launch-provider manuals describe different encapsulation and integration flows, so the transfer architecture should follow the selected campaign rather than a universal generic sequence.','falcon','vulcan'),
 {suppliers:[supplier('Beyond Gravity','Handling adapters, integration stands and trolleys','Examples of the equipment family; the modeled transfer support has no assigned manufacturer or certified capacity.','mgse','trolley')],alternatives:[alternative('Dedicated intermediate fixture','Provide a stable handoff point between two operations.','Adds tooling and a transfer, but can simplify access and interface control.'),alternative('Common support through several operations','Retain one compatible adapter or carrier longer in the campaign.','Reduces handoffs while imposing more requirements on the shared support.')],inspection:['Watch the change in support between the stand, crane and final interface. A disappearing tool in an animation is a sequence cue, not proof of a realizable removal path.'],terms:[term('Handoff','The transition of support or control from one system to another.'),term('Integration flow','The ordered arrangement of assembly, test and handling activities.')],relatedIds:['ground:checkout-stand','ground:lifting-frame','ground:fairing-carrier','flight:09.01','launch:vehicle']});
topics['cargo-load-bridge']=article('cargo-load-bridge',
 'The cargo loading bridge is a workbench concept for moving a large payload toward an integrated cargo-bay opening. It illustrates a possible geometric handoff between facility support and an internal carriage; it is not published Starship ground equipment or a provider-confirmed loading method.',
 P('A retained cargo enclosure changes the integration question. Instead of closing two fairing halves around the payload, the payload must pass through an opening and reach an internal attachment while tools and temporary supports remain removable. The bridge exists in the model to make that access and support problem visible.'),
 P('Conceptually, a bridge provides a continuous support path across a gap between the building-side fixture and the vehicle-side carriage. The payload’s load moves between supports as its position changes. Actual guide mechanisms, actuators, attachment details and load ratings have not been established here. The useful lesson is to follow the load and access envelope, not to infer an implemented transport system from the animation.'),
 P('A credible design would need a provider-controlled cargo interface, opening envelope, allowable loads, alignment tolerances and removal sequence. Differential movement between the facility and vehicle also affects any temporary bridge. NASA’s GSE and launch-equipment test references explain the engineering and verification context for such mechanisms, without validating this specific concept.','gse','letf'),
 {suppliers:[supplier('No provider-confirmed supplier','Workbench cargo-access concept','The rendered bridge is an educational integration concept. Published general MGSE products demonstrate the equipment class but do not establish Starship compatibility.','mgse')],alternatives:[alternative('Dedicated temporary loading bridge','Support an article across a defined gap during insertion.','Requires verified interfaces and a feasible withdrawal path after the payload is secured.'),alternative('Provider-defined integrated handling system','Use the launch provider’s eventual controlled cargo-handling architecture.','Its geometry and constraints must come from provider documentation; they are not resolved by this workbench.')],inspection:['Inspect the opening, payload sweep and bridge removal space. Treat the carriage and motion as conceptual geometry.'],terms:[term('Sweep envelope','The volume occupied by an article throughout its movement.'),term('Temporary support','Ground tooling removed before the vehicle enters its flight configuration.')],relatedIds:['launch:fairing','ground:lifting-frame','ground:transfer-support','flight:09.01']});

topics['cooling-pump']=article('cooling-pump',
 'The ground cooling pump moves coolant through the checkout thermal circuit. Its task is to overcome the pressure losses of hoses, passages, fittings and the heat exchanger so that heat can be carried away from the test article.',
 P('The pump supplies fluid motion; it is not itself the main heat-rejection device. A complete circuit also needs a way to collect heat from the spacecraft and transfer that heat to the facility or surrounding air. Keeping these roles separate helps explain why a pump can operate normally while the payload still runs too warm.'),
 P('A centrifugal pump transfers energy through a rotating impeller, while a positive-displacement pump moves a more defined volume per cycle. Delivered flow depends on both the pump and the resistance of the connected circuit. Eaton Boyd Thermal’s comparison is a useful introduction to these choices, and the Boyd chiller manual shows how a pump fits into a real ground loop.','pump','chiller'),
 P('Selection depends on required flow, pressure loss, fluid compatibility, temperature, cleanliness and how the circuit is controlled. Gas in the inlet or inadequate inlet conditions can impair operation; that is one reason the pump cannot be considered independently of the reservoir and plumbing. This is ground support even when the flight design uses passive heat pipes: a ground cooling fixture does not imply a pumped spacecraft architecture.'),
 {suppliers:[supplier('Eaton Boyd Thermal / Boyd','Liquid-cooling pumps and recirculating chillers','The linked literature explains equipment choices; the workbench assigns no pump curve, flow rating or coolant compatibility.','pump','chiller')],alternatives:[alternative('Centrifugal pump','Serve a continuous-flow cooling circuit with a suitable operating point.','Flow changes with circuit resistance, so the system curve matters.'),alternative('Positive-displacement pump','Move a controlled volume through a circuit with an appropriate control arrangement.','Pressure behavior and protection need to match the connected hardware.')],inspection:['Locate the pump relative to the reservoir, supply hose and return path. The casing does not reveal the unresolved internal pump type.'],terms:[term('System curve','The relationship between circuit flow and the pressure needed to drive it.'),term('Operating point','The flow and pressure at which a pump and its connected circuit settle.')],relatedIds:['ground:thermal','ground:cooling-reservoir','ground:heat-exchanger','flight:03.01']});
topics['cooling-reservoir']=article('cooling-reservoir',
 'The ground coolant reservoir holds the working inventory of the checkout cooling circuit and provides a defined connection point for the pump and return flow. It helps the ground loop accommodate changes in fluid volume and maintain a stable supply to the circulating equipment.',
 P('A cooling circuit is more than a pump and two hoses. The fluid must remain available at the pump inlet, and the system needs a defined inventory as temperatures and connected equipment change. The reservoir provides volume for that ground function. Its appearance does not establish the quantity of fluid carried by the spacecraft in flight.'),
 P('In a common recirculating chiller arrangement, coolant passes from the reservoir through the pump and process load, then returns through the cooling equipment. The exact ordering and whether the reservoir is vented or sealed depend on the actual product. Boyd’s manual provides a concrete example; it should not be treated as the plumbing drawing of this schematic cart.','chiller'),
 P('Reservoir design interacts with fluid compatibility, cleanliness, thermal expansion and pump inlet conditions. A useful inventory needs enough usable volume for the connected circuit, not merely a large external tank. Gas management and level indication are also system-level concerns, but the workbench does not resolve their mechanisms. NASA’s GSE reference is relevant when a standard commercial chiller is adapted into a spacecraft checkout system.','gse'),
 {suppliers:[supplier('Boyd','Recirculating process chillers','A documented example of a reservoir integrated with a pump, heat exchanger and controls. It is not an installed product selection.','chiller')],alternatives:[alternative('Reservoir-based recirculation','Provide accessible inventory within a packaged ground loop.','Adds volume and thermal mass while simplifying some service and inventory functions.'),alternative('Closed circuit with expansion accommodation','Use a sealed loop and a dedicated means of accepting volume change.','Can isolate the fluid from ambient air, with different pressure and gas-management requirements.')],inspection:['Separate the ground reservoir from flight fluid inventory. External dimensions in the model are not a stated usable capacity.'],terms:[term('Working inventory','The quantity of fluid participating in a particular circuit.'),term('Thermal expansion','The change in material volume as temperature changes.')],relatedIds:['ground:thermal','ground:cooling-pump','ground:heat-exchanger','flight:03.02']});
topics['heat-exchanger']=article('heat-exchanger',
 'The ground heat exchanger transfers energy from the spacecraft checkout circuit to another thermal sink while keeping the two fluid paths separate. It closes the heat-removal path that allows powered tests to continue without continually warming the ground coolant.',
 P('The spacecraft’s electronics produce heat during testing just as they do in operation. On the ground, a facility loop, chiller or air-cooled system can receive that heat. The heat exchanger is the boundary between the process side serving the test article and the side that rejects energy elsewhere.'),
 P('Heat flows through a separating wall from the warmer stream toward the cooler stream. Surface area, material conduction and the motion of both fluids influence the transfer. Plate exchangers use alternating channels to bring streams close across thin walls; Alfa Laval’s illustrated guide shows this clearly. The modeled block does not establish a particular internal plate or tube arrangement.','phe'),
 P('Temperature difference drives heat transfer, so an exchanger cannot bring the process stream below the available sink without additional refrigeration or another cooling mechanism. Pressure loss, fouling, compatibility and the consequence of cross-contamination also affect the choice. Boyd’s chiller manual shows how an exchanger integrates with controls and circulation, which is a broader function than an isolated metal block.','chiller'),
 {suppliers:[supplier('Alfa Laval','Plate heat exchangers','A real supplier example with clear explanatory diagrams; no particular product or thermal capacity is selected.','phe'),supplier('Boyd','Packaged recirculating chillers','An example of integrating heat exchange with the rest of the ground cooling circuit.','chiller')],alternatives:[alternative('Liquid-to-liquid exchanger','Reject process heat into a compatible facility circuit.','Compact integration may be possible, but depends on facility temperature and capacity.'),alternative('Packaged refrigerated chiller','Use a refrigeration system to control the process coolant.','Offers a wider temperature range while adding compressor power, controls and another heat-rejection path.')],inspection:['Trace both sides of the thermal boundary conceptually. The visible supply and return hoses alone do not show where the building ultimately rejects the heat.'],terms:[term('Approach temperature','The remaining temperature difference between a process stream and its thermal sink.'),term('Counterflow','An arrangement where the two heat-exchanger streams move in opposite overall directions.')],relatedIds:['ground:thermal','ground:cooling-pump','ground:cooling-reservoir','flight:03.01']});
topics['power-converter']=article('power-converter',
 'The ground power converter provides a controlled electrical supply for spacecraft checkout. It translates facility power into the form required at the ground service interface, while instruments and controls allow the response of the spacecraft power system to be observed.',
 P('Ground power keeps batteries available for their intended mission role and supports long test sessions. A converter may also be part of a simulator that reproduces a source the spacecraft will later encounter, such as a solar array. Those are different test purposes: a stiff laboratory supply and a realistic solar-array source need not behave the same way.'),
 P('A regulated converter measures its output and adjusts its power stage to follow a target. Some test systems can also absorb power or emulate changing source behavior. Keysight’s satellite battery and solar-array application guides explain why spacecraft power tests consider dynamic response and source characteristics, rather than voltage alone. The workbench cabinet does not identify a converter topology or bidirectional capability.','battery-test','sas'),
 P('Interface voltage, current limits, polarity, return paths, grounding and transient behavior must match the particular test. Cable resistance can make the voltage at the spacecraft differ from the voltage at the supply. Handover between external power, batteries and generated power is a system test with its own boundary; a stable reading on the ground converter does not prove that the flight distribution unit handled the transition correctly.'),
 {suppliers:[supplier('Keysight Technologies','Spacecraft power-source and battery-test equipment','A documented supplier example. The selected source, sink and emulation functions depend on the actual test architecture.','sas','battery-test')],alternatives:[alternative('Regulated ground DC supply','Provide a defined power bus for functional checkout.','Simple interpretation, but it may hide source dynamics experienced in flight.'),alternative('Programmable source emulator','Reproduce changing current–voltage characteristics or battery behavior.','More representative for selected tests, with greater model and control requirements.')],inspection:['The cabinet is ground equipment. Follow its service connection to the flight power interface rather than treating it as part of the spacecraft bus.'],terms:[term('Remote sense','Measuring voltage near the load to account for cable voltage drop.'),term('Source emulation','Reproducing the electrical behavior of another source instead of merely supplying a fixed voltage.')],relatedIds:['ground:power','flight:02.03','flight:02.02','site:connection-payload-power']});
topics['alignment-telescope']=article('alignment-telescope',
 'The alignment telescope establishes a precise optical line for comparing structural or instrument datums. It helps answer whether features are straight, offset or tilted relative to an agreed reference, rather than measuring an arbitrary distance to whatever surface happens to be visible.',
 P('Spacecraft assemblies need repeatable relationships between the structure, propulsion directions, sensors and payload interfaces. A telescope makes selected relationships observable through targets and reference optics. The measurement only becomes meaningful when those targets are tied to controlled physical datums and the coordinate convention is known.'),
 P('The instrument forms a sight line and compares the position of a target with its internal reference. Related optical-tooling methods include collimation and autocollimation, the latter using reflected light to reveal angular alignment. Brunson’s instrument documentation and introduction explain these modes. Not every telescope or configuration supports the same measurement; the model represents the class of tool.','brunson','brunson-learning'),
 P('Stable mounts, unobstructed sight lines, target quality, thermal conditions and a clear uncertainty budget matter as much as instrument resolution. A small displayed offset may arise from the fixture rather than the flight article. For a broad three-dimensional survey, a laser tracker or photogrammetry arrangement may complement a telescope. The choice should follow the geometric relationship being verified.'),
 {suppliers:[supplier('Brunson Instrument Company','Alignment telescopes and optical tooling','The linked 2024-series product is a real example. No specific accuracy or instrument configuration is assigned to this schematic telescope.','brunson')],alternatives:[alternative('Alignment telescope','Inspect a defined line, offset or angular relationship.','Requires an appropriate target and line of sight.'),alternative('Three-dimensional survey system','Measure a set of points and fit their coordinate relationships.','Offers broader geometry while adding registration, target-placement and uncertainty considerations.')],inspection:['Imagine the line of sight continuing from the telescope to a defined target. A convenient exterior edge is not automatically a metrology datum.'],terms:[term('Collimation','Establishing or checking an optical reference with parallel rays.'),term('Measurement uncertainty','The quantified range associated with confidence in a measurement result.')],relatedIds:['ground:alignment','ground:adapter','flight:05.03','flight:07.01']});
topics['rf-test-hat']=article('rf-test-hat',
 'The RF test hat is a local coupling fixture placed over or near an installed spacecraft antenna. It creates a controlled short path for functional radio checks while limiting interaction with the surrounding room.',
 P('A direct cable test can bypass the antenna and its installed connections. A local coupler includes more of that hardware in the test while avoiding the need for a complete far-field range. The hat can therefore support command, telemetry or continuity checks during integration, but its measurement boundary must be understood.'),
 P('A coupling antenna or probe exchanges energy with the flight antenna inside a controlled enclosure. Absorbing material and geometry shape the local field. NASA’s EO-1 antenna-test paper describes a hat-coupler application and contrasts it with a more extensive near-field antenna measurement. That paper is an X-band precedent; it does not establish an S-band product or calibrate this model.','eo1'),
 P('The relationship between coupler input and the spacecraft antenna depends on position, frequency and fixture construction. A successful functional exchange shows that the included signal path works under the test conditions; it does not measure the full radiation pattern, flight gain or interference environment. Mechanical contact and cleanliness also matter because the fixture sits close to flight hardware. Ground RF systems such as Terma’s SCOE provide the instruments behind this local interface.','rf-scoe'),
 {suppliers:[supplier('Terma','RF checkout instrumentation','An example of the rack-side equipment. The antenna-specific hat itself has no assigned supplier.','rf-scoe'),supplier('NASA Goddard and EO-1 collaborators','Published hat-coupler test example','A technical precedent for the method, not evidence of a matching product or frequency band.','eo1')],alternatives:[alternative('Conducted test connection','Measure the radio through a cable at an approved port.','Simplifies calibration but bypasses some installed antenna hardware.'),alternative('Antenna-range measurement','Measure fields or patterns in a purpose-built arrangement.','Provides different and more complete antenna evidence, with greater space and calibration requirements.')],inspection:['The hat is temporary ground tooling. It should be distinguished from the flight antenna beneath it.'],terms:[term('Coupler','A device that transfers a controlled portion of electromagnetic energy between paths.'),term('Near field','The region near an antenna where field structure is strongly dependent on distance and geometry.')],relatedIds:['ground:rf','flight:05.01','ground:environment']});
topics['ka-test-port']=article('ka-test-port',
 'The Ka-band test port is the controlled interface between the flight high-rate radio chain and ground measurement equipment. It allows engineers to examine a defined portion of the link without treating the entire room and antenna installation as an uncontrolled radio channel.',
 P('A payload data problem may originate in digital formatting, the modem, frequency conversion, amplification or antenna connections. A test port provides a repeatable place to insert or observe a signal and isolate those possibilities. Its usefulness depends on knowing exactly where it sits in the chain and what components it bypasses.'),
 P('The port connects to a calibrated measurement path using suitable RF hardware. Depending on the actual design it may be a direct interface, a coupled sample or a temporary test connection; the schematic does not resolve that topology. Terma’s RF checkout literature shows the wider measurement chain of converters, instruments and automated software that can be attached to such an interface.','rf-scoe','rf-brochure'),
 P('At high frequency, the connector or waveguide interface, cable loss, reflections and mechanical repeatability affect measurements. A reported power or error result must refer to a defined reference plane. A test port result also omits any excluded antenna or external propagation effects. Pairing it with end-to-end file checks helps distinguish RF performance from useful payload delivery, while keeping those conclusions separate.'),
 {suppliers:[supplier('Terma','Ka-capable spacecraft RF checkout systems','A documented equipment example. The workbench does not specify the port connector, frequency plan, impedance or allowable signal level.','rf-scoe')],alternatives:[alternative('Conducted reference-plane test','Connect instruments at a specified electrical interface.','Supports repeatability and isolation while excluding downstream hardware.'),alternative('Installed-antenna test','Measure through a coupler or a calibrated radiated arrangement.','Includes more of the installed path, with additional geometry and calibration requirements.','eo1')],inspection:['Follow the port back toward the flight radio and outward toward the ground receiver. Do not assume the visible socket is a product-accurate connector.'],terms:[term('Reference plane','The defined location to which an RF measurement is calibrated or referred.'),term('Return loss','A measure related to how much signal reflects from an impedance discontinuity.')],relatedIds:['ground:rf-ka','ground:data','flight:05.02']});
topics['optical-test-head']=article('optical-test-head',
 'The optical test head is the local reference instrument facing the spacecraft’s optical terminal. It can provide a controlled optical stimulus, collect the terminal’s beam or establish an alignment reference, depending on the test configuration.',
 P('The bench supplies stability and positioning; the head supplies the optical interface. That distinction matters because a mechanically aligned bench can still contain an incorrectly registered source, detector or reference optic. The test must relate the head’s optical axis to its mounting datum and then to the spacecraft’s own pointing reference.'),
 P('Reference optics can form a nearly parallel beam, focus received light onto a detector or relay a target into the terminal’s field of view. Safran and Jena-Optronik describe equipment in this category. The particular source, wavelength, detector and optical prescription are not established by this model, so a decorative lens should not be read as a complete instrument design.','ogse','jena'),
 P('Dynamic range, alignment stability, contamination and stray light affect the meaning of the result. A head used to verify pointing may not verify data modulation, and a data loopback may not verify absolute boresight. The TBIRD preflight work is useful further reading on how alignment and pointing evidence connect to a complete optical communication system.','tbird'),
 {suppliers:[supplier('Safran Reosc','Optical test and calibration equipment','A real supplier of specialized optical ground equipment.','ogse'),supplier('Jena-Optronik','Reference optics and optical metrology','A second source of real equipment examples; neither is identified as the installed workbench head.','jena')],alternatives:[alternative('Collimated target or source','Present a controlled angular reference to the terminal.','Useful for pointing tests, with calibration of the reference optical axis.'),alternative('Receiver head with independent metrology','Collect the emitted beam and compare it with an external reference.','Can expose outgoing alignment errors, while detector and bench properties enter the uncertainty.')],inspection:['Inspect the alignment between the head and flight aperture. The gap is a test path, not a simulated atmosphere or complete orbital range.'],terms:[term('Stray light','Light reaching a detector through unintended paths.'),term('Optical prescription','The detailed specification of optical surfaces, spacing and materials.')],relatedIds:['ground:rf-optical','ground:alignment','flight:05.03']});

const siteTopics={};
siteTopics['launch-position']=article('launch-position',
 'A launch position is the coordinated place where the prepared vehicle meets its ground structure, fluids, electrical services, access equipment and exhaust environment. It is a system of interfaces rather than only a concrete platform or service tower.',
 P('The site links a launch campaign to geography and infrastructure: the processing route, available utilities, access arrangements and the surrounding range. The selected catalog record supplies the actual location and evidence status. Those details matter because a future or inferred site should not be presented as a fully documented operating facility.'),
 P('Before departure, ground structures support or stabilize the vehicle, service equipment connects to it, and control systems monitor the combined configuration. At departure those services must reach their intended disconnected state while the exhaust-management system receives the engine environment. NASA’s Launch Complex 39B page provides a clear real example of how these functions coexist, but its mobile-launcher architecture is not universal.','pad'),
 P('A site design must coordinate spatial envelopes and interfaces across civil, mechanical, fluid and electrical systems. A change in vehicle exhaust geometry can affect nearby structures; a changed access arrangement can affect umbilical routes. Provider payload guides describe another boundary: how the payload campaign meets launch-site operations. The workbench uses the selected site’s documented or explicitly inferred topology rather than assigning every pad the same hardware.','falcon','ariane','vulcan'),
 {suppliers:[supplier('Launch provider and site operator','Launch complex and mission integration services','Responsibility follows the selected site and provider. NASA Kennedy is a documented institutional example, not the operator of every modeled location.','pad')],alternatives:[alternative('Fixed service infrastructure','Bring the vehicle to permanent pad structures and interfaces.','Concentrates infrastructure at the pad but ties vehicle access closely to that location.'),alternative('Mobile integration or launch platform','Move part of the support and service architecture with the vehicle.','Can shift work away from the pad while adding transport and mobile-to-fixed interfaces.')],inspection:['Use the catalog’s location and evidence fields before interpreting the geometry. A schematic tower is not an as-built site survey.'],terms:[term('Range','The broader operational area and supporting organization associated with launch activities.'),term('Ground-to-vehicle interface','The boundary where a facility service or support connects to the launch vehicle.')],relatedIds:['site:launch-table','site:exhaust-path','site:pad-support','site:commodity-services','ground:facility','launch:vehicle']});
siteTopics['launch-table']=article('launch-table',
 'The launch table supports the vehicle at its ground bearing interfaces and leaves the intended paths for engine exhaust. It connects the launch vehicle’s local support geometry to the much larger civil structure beneath the pad.',
 P('A vehicle standing upright has to transmit its weight, environmental loads and pre-departure engine-related loads into the ground through controlled interfaces. The table is part of that load path. Its openings and surrounding structure also influence how exhaust reaches the designated trench, deflector or other selected exhaust arrangement.'),
 P('Bearing seats or other support features transfer loads from the vehicle into the table and foundation. Restraints may hold or stabilize the vehicle until the defined release event, but the table and restraint mechanism remain distinct components. NASA’s pad and flame-trench references illustrate the relationship between structural support and exhaust civil works for one real launch complex.','pad','deflector'),
 P('The support interface depends on vehicle geometry and launch architecture; it should not be inferred solely from rocket diameter. Structural stiffness, local load introduction, thermal exposure, access to lower services and clearance for separation all interact. The table in the workbench is schematic, so its visible thickness or opening shape does not establish an allowable load, fatigue life or validated exhaust environment.'),
 {suppliers:[supplier('Launch provider and civil/mechanical contractors','Vehicle-specific bearing and launch structures','The responsible supplier is not established for the schematic table. NASA’s documented LC-39B infrastructure is a comparison case.','pad','deflector')],alternatives:[alternative('Permanent launch table','Integrate the bearing structure directly with fixed pad works.','Simplifies some fixed interfaces while constraining integration and maintenance to the pad.'),alternative('Mobile launch structure','Carry the vehicle’s support interface on a moving platform.','Changes load paths, transport demands and connections to fixed site services.')],inspection:['Trace the bearing points to the table and then toward the foundation. Inspect the exhaust openings separately from the restraint jaws.'],terms:[term('Bearing interface','The contact arrangement through which structural load is transferred.'),term('Foundation','The civil structure that transfers loads into the ground.')],relatedIds:['site:restraints','site:exhaust-path','site:launch-position','launch:core']});
siteTopics.restraints=article('restraints',
 'Launch restraints keep the vehicle in a defined ground relationship until it is meant to depart. They are the local mechanisms at the bearing interface, distinct from the table that supports them and from service umbilicals that supply fluids or electricity.',
 P('The ground-to-flight transition requires several systems to change state in a coordinated way. A restraint must carry its intended ground loads and then allow the required vehicle motion without leaving an interfering attachment. Exactly how it does that is a vehicle-specific design choice; the modeled jaws communicate the function rather than a provider’s detailed mechanism.'),
 P('A restraint engages a defined structural feature and transfers its load into the launch table. Release changes the mechanical constraint. Real implementations can differ in actuation, geometry and verification methods, so a visible hydraulic-looking element does not establish the actual provider architecture. NASA’s Launch Equipment Test Facility describes the dedicated infrastructure used to test ground mechanisms and release interfaces.','letf'),
 P('Key questions include the loads before release, positional tolerances, the required clear state after release and the information available to confirm that state. Neighboring fluid and electrical services must be considered without conflating their release functions. NASA’s GSE standard offers a documentation and design reference; it does not certify a generic restraint rendered in the workbench.','gse'),
 {suppliers:[supplier('Launch vehicle provider','Hold-down and release hardware','The provider’s controlled design governs the actual mechanism; no manufacturer or release rating is assigned here.'),supplier('NASA Kennedy Launch Equipment Test Facility','Ground mechanism and interface testing','An institutional example of the facilities used to verify such equipment classes.','letf')],alternatives:[alternative('Actively released restraint','Use a controlled mechanism to remove a structural constraint.','Requires defined actuation, state confirmation and clearance behavior.'),alternative('Other provider-defined support and release architecture','Implement the launch vehicle’s particular departure interface.','Must be evaluated from the actual vehicle design; different concepts are not interchangeable.')],inspection:['Compare the engaged and clear positions in the animation. The motion is explanatory and does not demonstrate release timing or structural qualification.'],terms:[term('Constraint','A restriction on an article’s permitted movement.'),term('Clear state','The condition in which a released interface no longer obstructs the intended motion.')],relatedIds:['site:launch-table','site:pad-support','launch:core']});
siteTopics['exhaust-path']=article('exhaust-path',
 'The exhaust-path allocation represents the civil and structural works that receive and direct the launch vehicle’s engine plume. Depending on the selected site, this may involve a trench, deflector, exposed opening or another documented arrangement.',
 P('An engine produces a high-energy flow that interacts with the nearby ground and structures. The site has to accommodate that flow without assuming that empty space below the engine is enough. The exhaust path is therefore part of launch-system design, affecting thermal exposure, acoustic conditions, pressure loads and the placement of surrounding equipment.'),
 P('A deflector changes the direction of the flow, while a trench or open channel provides an intended route away from the immediate vehicle area. Water systems may address selected thermal or acoustic effects, but their purpose and geometry depend on the site. NASA’s LC-39B flame-trench construction account and water-system test article provide concrete examples of these coordinated civil and fluid systems.','deflector','deluge'),
 P('The correct geometry follows the launcher’s engine arrangement and the site’s actual design. A schematic trench is not a plume simulation, and its appearance cannot establish erosion resistance or an acoustic level at the payload. The catalog may explicitly leave an exhaust feature unresolved when public evidence is insufficient; in that case this page teaches the function without manufacturing an as-built layout.'),
 {suppliers:[supplier('Launch-site civil and mechanical contractors','Exhaust civil works and associated infrastructure','The specific supplier is not established by this workbench. NASA Kennedy’s published construction is an illustrative project.','deflector')],alternatives:[alternative('Trench and deflector arrangement','Turn and route exhaust through dedicated civil works.','Requires geometry and materials appropriate to the selected launch environment.'),alternative('Other open or distributed exhaust arrangement','Accommodate the plume through a different provider-defined layout.','Changes nearby exposure and infrastructure requirements; it must be assessed as a complete site design.')],inspection:['Follow the path from engine exits through the table openings to the site works. A context view may show the table and exhaust structure together.'],terms:[term('Plume impingement','Interaction of an engine exhaust flow with a surface.'),term('Ignition overpressure','A transient pressure environment associated with engine ignition and the nearby flow geometry.')],relatedIds:['site:launch-table','site:water-supply','site:pad-support','launch:core']});
siteTopics['pad-support']=article('pad-support',
 'Pad support equipment provides the selected vehicle’s access, stabilization or service-routing architecture near the launch position. A service tower, mobile structure and transporter-erector solve different combinations of those tasks; the active catalog identifies which concept is represented.',
 P('The vehicle needs connections and access before launch, but those structures must also coexist with its departure and exhaust environment. Some architectures carry services on a tower, while others retain an interface structure associated with transport and erection. The useful comparison is the set of functions and interfaces, not a single universal tower shape.'),
 P('A support structure carries its own equipment and routes loads or services into foundations or a mobile base. Movable arms or vehicle-adjacent sections may change position before departure. NASA’s mobile-launcher umbilical fact sheet provides one documented tower architecture, while the Falcon payload guide provides context for a different provider’s ground integration flow. Neither should be copied indiscriminately onto other modeled sites.','umbilicals','falcon'),
 P('Access envelopes, vehicle motion, utility routes and exhaust clearance compete for space. The support’s stiffness and alignment also affect nearby disconnect interfaces. Where provider details are not public, the workbench keeps a schematic or unavailable representation rather than asserting internal mechanisms. The selected record’s evidence note is the place to distinguish established features from architecture-level inference.'),
 {suppliers:[supplier('Launch provider and ground-system contractors','Vehicle access and service support structures','The selected site determines responsibility. Published NASA and SpaceX material are comparison references, not a common supplier definition.','umbilicals','falcon')],alternatives:[alternative('Fixed service tower','Support access and umbilicals from a permanent structure.','Offers a stable facility interface while requiring clearance from the departing vehicle.'),alternative('Transporter-associated service structure','Combine transport or erection interfaces with some pad services.','Can consolidate equipment, with additional motion and transition interfaces.')],inspection:['Identify whether the selected view depicts a tower or transporter-related structure. Follow each service arm to its own connection rather than treating the whole structure as one umbilical.'],terms:[term('Transporter-erector','Ground equipment that moves a vehicle and changes it from transport to launch orientation.'),term('Service arm','A structure that brings a ground service or access route near the vehicle.')],relatedIds:['site:launch-position','site:utility-distribution','site:launch-table','launch:vehicle']});
siteTopics['water-supply']=article('water-supply',
 'The launch-site water allocation represents the supply and distribution used for the selected pad’s exhaust-related thermal or acoustic functions. It is separate from propellant services and from the spacecraft’s ground cooling cart.',
 P('Water can absorb heat, alter the local plume environment and help manage acoustic or ignition-related loads, depending on where and how the site system is designed. A supply vessel alone does not define that performance: distribution geometry, flow delivery and coordination with the exhaust works are all part of the system.'),
 P('Water moves from a site supply through distribution paths to designated outlets around the launch structure. NASA’s LC-39B water-system test article is a concrete example of verifying a complete delivery arrangement before launch. Its figures and layout belong to that site; they are not design values for the other launchers represented here.','deluge'),
 P('The system boundary includes stored or supplied water, piping, support structures, outlet geometry and the receiving civil works. Required inventory and delivery behavior depend on the selected vehicle and pad, so the size of a schematic tank or manifold should not be read as an engineering specification. Where the model lacks evidence for a particular water architecture, the catalog explicitly marks that limitation. NASA’s pad overview helps place this service among the surrounding site systems.','pad'),
 {suppliers:[supplier('Launch-site operator and fluid-system contractors','Pad water supply and distribution','The actual supplier and capacity are not established for the schematic allocation. NASA Kennedy provides a documented example of system-level testing.','deluge')],alternatives:[alternative('Dedicated stored-water delivery','Provide a site system designed around a defined launch demand.','Requires storage, distribution and civil integration sized together.'),alternative('Other provider-defined cooling or acoustic architecture','Use the selected pad’s documented combination of geometry and fluids.','Effectiveness must follow that complete design; one site’s water arrangement is not a universal template.')],inspection:['Distinguish the supply boundary, manifold and outlets from the exhaust trench. Visible water-system geometry is not a calculated sound-suppression result.'],terms:[term('Manifold','A component that distributes a common fluid supply into several paths.'),term('Acoustic environment','The pressure fluctuations and sound levels experienced by nearby structures and hardware.')],relatedIds:['site:exhaust-path','site:launch-table','site:commodity-services','ground:thermal']});
siteTopics['lightning-protection']=article('lightning-protection',
 'Launch-site lightning protection provides intended interception and current paths around exposed vehicle and ground systems. It is a coordinated site electrical design, separate from the small bonding connection between two pieces of equipment.',
 P('A tall vehicle and nearby structures can be exposed to atmospheric electrical activity. The protection system aims to manage where a strike attaches and how its current reaches ground, while the broader electrical design addresses induced effects on cables and electronics. Its geometry must therefore be considered with the protected volume and connected services.'),
 P('One real architecture uses towers and suspended conductors around the launch area. NASA’s LC-39B article explains this catenary approach. Other sites may use different arrangements, and the workbench should only depict the selected site’s supported topology. A tower count from one launch complex is not a rule for another.','lightning'),
 P('Current paths, bonding, grounding and the routing of sensitive circuits interact. A visible mast does not establish a complete protection design or prove immunity of the payload electronics. NASA Kennedy’s grounding and EMI standard is useful reading on the wider relationship between facilities and ground equipment. The catalog’s evidence status identifies whether a particular site feature is documented or unresolved.','bonding'),
 {suppliers:[supplier('Launch-site operator and electrical engineering contractors','Site lightning protection and grounding networks','The model does not assign a contractor or certified protection level. NASA Kennedy’s published installation is a reference example.','lightning','bonding')],alternatives:[alternative('Catenary interception system','Use elevated conductors to define preferred strike paths around a protected area.','Requires a site-specific structural and grounding design.'),alternative('Other site-specific interception and grounding layout','Use the arrangement established for the actual launch complex.','Protection depends on the complete geometry and electrical network, not the appearance of one mast.')],inspection:['Look for the relationship between the vehicle, interception conductors and the ground-side network. Do not confuse a lightning mast with an umbilical tower.'],terms:[term('Catenary conductor','A suspended conductor forming part of an overhead interception arrangement.'),term('Bonding','Intentional electrical connection between conductive structures to control their relative potential.')],relatedIds:['site:utility-distribution','site:connection-vehicle-bond','site:launch-position']});
siteTopics['commodity-services']=article('commodity-services',
 'Launch-site commodity services provide the fluids required by the vehicle and its ground systems. The category can include oxidizer, fuel, inert gases and pressurants, with distinct storage and distribution arrangements for each medium.',
 P('A propellant is one use of a commodity, not a synonym for every fluid on site. Nitrogen or helium may support purge, pressure or other service functions without being burned as the main propellant. The selected catalog lists the species supported by its evidence; it deliberately does not infer tank counts or inventory from symbolic geometry.'),
 P('At system level, supply equipment receives and stores or generates the required medium, distribution routes it toward a service boundary, and an umbilical connects the relevant ground path to the vehicle. NASA Kennedy’s servicing capabilities and commodity FAQ explain the range of engineering and support functions behind this chain. Each medium has its own material, temperature, cleanliness and interface requirements.','propellants','fluid-faq'),
 P('The source of a commodity and the manufacturer of a launch vehicle are often different organizations. Agency supply awards illustrate industrial procurement of gases and cryogenic liquids, but they do not identify the supplier at every modeled commercial pad. A shared visual tank icon is therefore a category marker, not evidence that two fluids share storage or that one supplier serves the selected mission.','gas-supply'),
 {suppliers:[supplier('Air Liquide','Space-sector industrial gases and cryogenic services','A real supplier example with documented space applications; not an installed supplier selection.','airliquide'),supplier('NASA Kennedy','Propellant and high-pressure-gas support','An institutional reference for commodity infrastructure and engineering.','propellants')],alternatives:[alternative('Dedicated bulk supply infrastructure','Provide medium-specific storage and distribution for the site.','Can support repeat campaigns while creating fixed capacity and interface commitments.'),alternative('Campaign-specific supply arrangements','Bring compatible supply capability to an approved service boundary.','Offers flexibility, with logistics and infrastructure interfaces that still require definition.')],inspection:['Open the individual commodity pages. A symbol indicates service presence, not a measured inventory or a physical vessel count.'],terms:[term('Commodity','A supplied fluid or gas used by the vehicle or its ground infrastructure.'),term('Pressurant','A gas used to establish or maintain pressure in another system.')],relatedIds:['site:utility-distribution','site:commodity-lox','site:commodity-lng','site:commodity-lh2','site:commodity-rp1','site:commodity-n2','site:commodity-he']});
siteTopics['utility-distribution']=article('utility-distribution',
 'Ground utility distribution is the shared boundary between fixed site services and the individual circuits routed toward the vehicle. It organizes electrical power, data, bonding, environmental conditioning and fluid interfaces without implying that those services use interchangeable hardware.',
 P('A vehicle-facing connector is only the final segment of a longer service chain. Behind it are supplies, instruments, control systems and fixed infrastructure. Showing a common boundary makes those dependencies visible while avoiding an invented detailed piping-and-cabling drawing for every launch site.'),
 P('Each service crosses the boundary with a defined source, destination and direction. Electrical circuits carry energy or signals; fluid circuits carry a specified medium; a bonding path establishes an electrical relationship between structures. The selected catalog’s connection records make these distinctions explicit. NASA’s umbilical fact sheet illustrates the variety of services carried by one real launcher architecture.','umbilicals'),
 P('Shared location does not mean shared function. Power returns, protective bonds and data shields need their intended roles; conditioned air cannot be treated as a propellant purge simply because both use a duct or hose. NASA Kennedy’s bonding and EMI standard explains the electrical coordination side, while its fluid-service overview provides the complementary fluid boundary.','bonding','propellants'),
 {suppliers:[supplier('Site operator and ground-system integrator','Integrated utility interfaces','The actual suppliers depend on the selected site and service. This record is a symbolic system boundary, not a commercial distribution cabinet.','pad','gse')],alternatives:[alternative('Central distribution boundary','Coordinate services through a defined common interface area.','Can simplify integration visibility while concentrating routing and access demands.'),alternative('Distributed service interfaces','Place service boundaries near their particular consumers.','May shorten local routes while increasing the number of coordinated site interfaces.')],inspection:['Follow individual service lines to their own connection pages. The boundary object does not imply that every line enters one physical box.'],terms:[term('Service boundary','The agreed point at which responsibility or interface definition changes.'),term('Interface direction','The stated flow of energy, information or fluid between source and destination.')],relatedIds:['site:commodity-services','site:pad-support','site:connection-vehicle-power','site:connection-vehicle-data','site:connection-vehicle-bond']});

const commodityTopics={},umbilicalTopics={},connectionTopics={};
const factValue=(record,label)=>record.facts?.find(item=>item.label===label)?.value;
function cloneArticle(value){
 return {...value,sections:value.sections.map(section=>({...section,paragraphs:section.paragraphs.map(p=>({...p,sources:[...(p.sources||[])]}))})),suppliers:value.suppliers.map(item=>({...item,sources:[...(item.sources||[])]})),alternatives:value.alternatives.map(item=>({...item,sources:[...(item.sources||[])]})),inspection:[...value.inspection],terms:value.terms.map(item=>({...item})),relatedIds:[...value.relatedIds],sourceIds:[...value.sourceIds]};
}
export function groundKnowledge(record,catalog,hardware){
 if(!record||!['ground','site'].includes(record.category))return null;
 let template;
 if(record.category==='ground')template=topics[record.id.slice(7)];
 else{
  const localId=record.id.slice(5);
  if(localId.startsWith('commodity-')&&localId!=='commodity-services'){
   const medium=localId.slice(10),aliases={rp1:'kerosene',lng:'methane',lh2:'hydrogen',n2:'nitrogen',he:'helium'};
   template=commodityTopics[aliases[medium]||medium];
  }else if(localId.startsWith('connection-'))template=connectionTopics[factValue(record,'Medium')]||connectionTopics.unknown;
  else if(localId.startsWith('umbilical-')){
   const children=(catalog?.records||[]).filter(child=>child.parentId===record.id),media=children.map(child=>factValue(child,'Medium'));
   template=media.includes('conditioned-air')?umbilicalTopics.environmental:media.length&&media.every(m=>['power','data','grounding'].includes(m))?umbilicalTopics.electrical:umbilicalTopics.fluid;
  }else template=siteTopics[localId];
 }
 if(!template)return null;
 const value=cloneArticle(template);
 if(record.category==='ground'&&['ground:thermal','ground:cooling-pump','ground:cooling-reservoir','ground:heat-exchanger'].includes(record.id)){
  const passive=hardware?.energySystem?.thermal?.kind==='passive-local';
  value.sections.find(s=>s.id==='operation').paragraphs.push(P(passive?'The selected spacecraft uses a passive local thermal architecture. These ground fluid components therefore describe external conditioning equipment; they do not imply a flight coolant charge, flight pump or a ground-fill operation for the spacecraft.':'For this selected thermal architecture, distinguish the external conditioning circuit from the spacecraft’s own heat-transport hardware. A service connection does not establish that the two circuits share fluid, pressure limits or materials; that interface must be defined separately.'));
 }
 if(record.id.startsWith('site:connection-')){
  value.relatedIds=[record.parentId,...value.relatedIds].filter(Boolean);
 }
 if(record.id.startsWith('site:umbilical-'))value.relatedIds=[...(catalog?.records||[]).filter(child=>child.parentId===record.id).map(child=>child.id),...value.relatedIds];
 value.relatedIds=[...new Set([...value.relatedIds,...(record.relatedIds||[])])].filter(id=>id!==record.id);
 if(record.render?.unavailable)value.inspection.push('This allocation has no resolved model in the selected configuration. Use the catalog’s availability and evidence note to understand that limit.');
 return value;
}

Object.assign(groundKnowledgeSources,{
 'ground-rp1-product':source('RP-1 Propellant, Rocket-Grade Kerosene','American Hydrocarbons / Haltermann Solutions','https://www.haltermannsolutions.com/products?id=124009/rp-1-propellant-rocket-grade-kerosene','Supplier product page','A real catalog entry for rocket-grade kerosene. The stated specification belongs to that offering, not every kerosene-fueled launcher.'),
 'ground-rp1-development':source('Rocket Fuel Development','Haltermann Solutions','https://www.haltermannsolutions.com/tech-talk/rocket-fuel-development','Supplier technical article','Explains why rocket-grade kerosene is a controlled fuel specification and why composition can matter even within a specification.'),
 'ground-linde-space':source('Cryogenic Gases to Support Engine Testing and Launch','Linde','https://www.linde-gas.com/industries/space/engine-testing-and-launch','Supplier application overview','An industry overview of cryogenic propellants and the separate roles of cooling, purge and pressurization gases.'),
 'ground-methane-history':source('Rocket Laboratory — Final Years','NASA Glenn','https://www.nasa.gov/rocket-laboratory-final-years/','Technical history','The methane-for-thruster-systems section gives a documented example of methane/oxygen research and its system-level motivations.','Methane for Thruster Systems')
});
commodityTopics.lox=article('commodity-lox',
 'Liquid oxygen, usually abbreviated LOX, supplies the oxidizer for many liquid-propellant launch vehicles. It carries the oxygen needed for combustion rather than relying on atmospheric air, allowing the engine to continue operating as the vehicle leaves the atmosphere.',
 P('LOX is the oxidizer side of a propellant pair; methane, hydrogen or kerosene may provide the fuel side. The same oxidizer name does not imply that those engines share fuel hardware or loading interfaces. The site commodity page represents the ground supply function, while the launch vehicle’s tanks and engine system are separate articles.'),
 P('Oxygen is stored and delivered in a cryogenic liquid state when that is the selected vehicle architecture. The site system has to preserve the required material condition between supply and the ground-to-vehicle connection. NASA Kennedy’s commodity information and Linde’s space-gas overview provide examples of how this medium sits within a larger supply and distribution system.','fluid-faq','linde-space'),
 P('Material compatibility, cleanliness, heat input and the controlled service interface are central design concerns. A tank icon does not reveal usable inventory, replenishment capability or delivery conditions. Nor is an oxygen-service component interchangeable with a fuel component merely because the external fittings look alike. The modeled allocation intentionally leaves vessel count and capacity unspecified unless the source evidence establishes them.'),
 {suppliers:[supplier('Industrial gas suppliers','Launch-site oxygen supply','NASA’s dated liquid oxygen and nitrogen procurement provides actual supplier examples; it does not identify the provider for this selected pad.','gas-supply'),supplier('Linde','Cryogenic gases for space applications','A documented commercial supplier category, not an installed sourcing decision.','linde-space')],alternatives:[alternative('Bulk cryogenic oxygen supply','Serve the vehicle through dedicated oxygen-compatible infrastructure.','Requires an integrated storage and distribution architecture.'),alternative('Different propulsion chemistry','Select a vehicle designed around another oxidizer system.','Changes the engine, tanks and ground infrastructure; it is not a substitute fluid for a LOX system.')],inspection:['Distinguish the ground oxygen service from the vehicle oxidizer tank and from any nitrogen cooling service.'],terms:[term('Oxidizer','A substance that enables the chemical reaction with the fuel.'),term('Cryogenic liquid','A liquid maintained at a very low temperature relative to ordinary ambient conditions.')],relatedIds:['site:commodity-services','site:connection-core-oxidizer','site:connection-upper-oxidizer','launch:core','launch:upper']});
commodityTopics.methane=article('commodity-methane',
 'The methane fuel service supplies the ground-side liquid fuel for the selected methane/oxygen launcher architecture. It is paired with a separate oxidizer service and should not be confused with either the spacecraft’s own maneuvering propellant or a general-purpose natural-gas utility.',
 P('Methane is a hydrocarbon fuel. In a rocket system it is carried along with an oxidizer, usually oxygen for the architecture represented here. NASA Glenn’s methane research history provides a documented example of interest in methane’s system properties, including its greater liquid density than hydrogen. Those advantages must be evaluated with the complete engine and vehicle.','methane-history'),
 P('A site fuel system maintains a specified fuel condition and delivers it through its own distribution and vehicle interface. The catalog may use LNG as a commodity label, but commercial liquefied natural gas can have a composition that differs from a mission’s controlled methane specification. The actual required grade, state and compatibility come from the vehicle’s interface documentation.'),
 P('Storage volume, heat leakage, fuel composition and material compatibility influence the ground architecture. A service line is not evidence for a particular storage-tank count or an operating procedure. NASA Kennedy’s propellant-services overview is useful for understanding the engineering responsibilities around fluid systems without treating any one facility’s arrangement as universal.','propellants'),
 {suppliers:[supplier('Vehicle-approved fuel supplier','Specified methane-rich or methane fuel supply','No supplier or fuel grade is established for this schematic service. Linde’s space-sector literature is an example of industrial gas infrastructure, not evidence of a methane contract for the selected pad.','linde-space')],alternatives:[alternative('Methane/oxygen vehicle architecture','Use tanks, engines and infrastructure designed for this propellant pair.','Requires cryogenic fuel services and compatibility with the specified fuel composition.'),alternative('Kerosene/oxygen or hydrogen/oxygen architecture','Choose a different complete propulsion system.','Changes tank volume, thermal requirements and engine design; fuels are not interchangeable at the service port.')],inspection:['Trace the fuel service separately from LOX. The symbolic vessel is a category indicator, not a storage-capacity estimate.'],terms:[term('LNG','Liquefied natural gas, a commodity description whose composition must be distinguished from a controlled rocket-fuel specification.'),term('Propellant pair','The selected fuel and oxidizer used together by an engine.')],relatedIds:['site:commodity-lox','site:commodity-services','site:connection-core-fuel','launch:core']});
commodityTopics.hydrogen=article('commodity-hydrogen',
 'Liquid hydrogen, or LH2, is a cryogenic rocket fuel used with a separate oxidizer such as liquid oxygen. The site service supplies the fuel to the selected vehicle stage and is distinct from any helium pressurization or nitrogen service nearby.',
 P('Hydrogen has a very low liquid density compared with many other rocket fuels, so its use affects tank volume and ground infrastructure as well as engine performance. NASA Glenn’s propellant research history offers a useful comparison with methane. A vehicle that uses hydrogen in an upper stage may still use a different fuel in its core; the connection’s destination matters.','methane-history'),
 P('The ground system preserves a very cold fluid state through storage and distribution to the vehicle interface. Heat entering the system affects the fluid condition and inventory. The function is therefore broader than moving liquid from one visible vessel to another. Linde’s space-gas overview and NASA’s supply announcements show the industrial infrastructure supporting such fuel services.','linde-space','hydrogen-supply'),
 P('Thermal insulation, material compatibility, leakage characteristics and the definition of each service boundary are central design issues. The workbench does not resolve insulation performance, storage capacity or operating limits. The site allocation also does not imply that hydrogen is used by every stage: use the selected connection’s source and destination and the launcher’s documented propulsion architecture.'),
 {suppliers:[supplier('Air Products and Plug Power','Liquid hydrogen supply','NASA identifies these companies in a dated supply award. This is evidence of real industry participation, not a supplier assignment for the selected launch site.','hydrogen-supply'),supplier('Linde','Cryogenic propellant supply services','An additional commercial example of the supply category.','linde-space')],alternatives:[alternative('Hydrogen/oxygen propulsion architecture','Design the engine, stages and ground services around hydrogen fuel.','Offers a distinct propulsion trade while placing strong demands on cryogenic storage and tank volume.'),alternative('Methane or kerosene fuel architecture','Select a vehicle designed around a denser fuel.','Changes propulsion performance, tank geometry and facility interfaces rather than replacing the fuel in an existing hydrogen stage.')],inspection:['Check which stage the hydrogen connection serves. Do not infer that all visible fuel lines carry the same medium.'],terms:[term('Boil-off','Conversion of stored liquid to vapor as heat enters the fluid.'),term('Fuel density','Fuel mass per unit volume, which affects required tank volume.')],relatedIds:['site:commodity-lox','site:connection-upper-fuel','site:commodity-services','launch:upper']});
commodityTopics.kerosene=article('commodity-kerosene',
 'The kerosene service supplies a hydrocarbon fuel for a launcher designed around that fuel family. RP-1 is a specified rocket-grade kerosene; a generic kerosene label should not be read as proof that a particular vehicle uses the same grade or supplier.',
 P('Kerosene is a mixture rather than one pure chemical. Rocket-fuel specifications control relevant properties and impurities because the fuel participates in combustion and may also pass through engine cooling passages. Haltermann Solutions’ development article explains why fuels meeting a specification can still differ in composition.','rp1-development'),
 P('The ground service links a controlled fuel supply to the vehicle’s fuel connection. Unlike a cryogenic liquid-hydrogen system, a kerosene architecture does not require the same extremely low fuel storage temperature, although the actual delivery condition remains vehicle-specific. NASA Kennedy’s commodity FAQ identifies RP-1 as a distinct supplied product among several launch-site fluids.','fluid-faq'),
 P('Specification, cleanliness, compatibility and traceability matter more than a generic tank color. The site’s symbolic inventory should not be interpreted as a measured volume or as ordinary aviation fuel being substituted into a rocket. Fuel choice is coupled to the engine and stage design; changing it can alter cooling behavior, deposits, density and operating characteristics.'),
 {suppliers:[supplier('American Hydrocarbons / Haltermann Solutions','RP-1 rocket-grade kerosene','A verified supplier product listing. It is an example of the RP-1 market, not evidence that the modeled provider buys this product or that every kerosene service is RP-1.','rp1-product')],alternatives:[alternative('Specified rocket-grade kerosene','Use fuel meeting the vehicle’s controlled requirement.','Combines dense liquid storage with composition and cleanliness constraints.'),alternative('Another approved propulsion architecture','Choose a launcher designed for methane, hydrogen or another fuel system.','Changes engines, tanks and ground services; it is not an interchangeable commodity choice at an existing interface.')],inspection:['Read the selected commodity label and launcher context. A generic kerosene allocation has less specificity than a documented RP-1 requirement.'],terms:[term('RP-1','A specification-controlled rocket-grade kerosene.'),term('Fuel traceability','The ability to connect a supplied batch with its identity, specification and supporting records.')],relatedIds:['site:commodity-lox','site:commodity-services','site:connection-core-fuel','launch:core']});
commodityTopics.nitrogen=article('commodity-nitrogen',
 'Nitrogen is a support commodity rather than the main fuel or oxidizer in the launch architectures represented here. Depending on the actual system, gaseous or liquid nitrogen can support environmental control, purge functions or cooling equipment.',
 P('A launch site needs controlled environments as well as propellants. Nitrogen can provide an atmosphere different from ambient air or act as a low-temperature thermal resource. The specific purpose must be identified for each service; the presence of nitrogen storage does not prove that every connected enclosure is purged with nitrogen.'),
 P('The supply system provides the required state and quality to its designated ground consumers. Linde’s space application overview distinguishes cooling, purging and pressurization services from fuel and oxidizer supply. NASA Kennedy’s commodity information also distinguishes liquid and gaseous nitrogen and their controlled specifications.','linde-space','fluid-faq'),
 P('Purity, moisture, pressure state, temperature and compatibility determine whether a supply is appropriate for a particular interface. Conditioned payload air and nitrogen are different services even when both arrive through ducts or hoses. The workbench commodity icon identifies an allocation, not a complete gas-generation, vaporization or distribution design, and it assigns no vessel capacity.'),
 {suppliers:[supplier('Industrial gas suppliers','Nitrogen supply for agency and space-sector applications','NASA’s liquid nitrogen and oxygen supply award documents actual providers. It does not establish the supply chain of this modeled pad.','gas-supply'),supplier('Linde','Space-sector support gases','A real application example covering non-propellant fluid functions.','linde-space')],alternatives:[alternative('Delivered liquid or gaseous nitrogen','Use a specified industrial supply arrangement matched to the consumer.','Requires appropriate storage, conversion and distribution for the needed state.'),alternative('Another controlled environmental service','Use conditioned air or another approved gas where the application permits it.','Different moisture, oxygen content, thermal and compatibility requirements mean these services cannot be substituted by appearance alone.')],inspection:['Keep nitrogen separate from LOX and from the payload conditioned-air connection. Similar symbols represent different media.'],terms:[term('Purge gas','A specified gas used to establish a controlled environment in a system or enclosure.'),term('Dew point','A measure related to the moisture content of a gas.')],relatedIds:['site:commodity-services','site:commodity-he','site:connection-payload-air','site:water-supply']});
commodityTopics.helium=article('commodity-helium',
 'Helium is a lightweight, chemically inert support gas used in selected pressure and test functions. At the launch site it is a supplied commodity with its own distribution boundary, not the vehicle’s main fuel or oxidizer.',
 P('A pressure system needs a gas compatible with its working fluid, temperatures and materials. Helium’s properties make it useful in many aerospace applications, but the actual role depends on the vehicle. A ground helium allocation does not by itself reveal whether the vehicle uses helium for tank pressurization, a test function or another service.'),
 P('The ground system makes helium available in the required state and condition at the approved interface. NASA Kennedy lists helium among its supplied commodities, while Linde’s space overview discusses pressurization and other support-gas roles. The spacecraft may have a separate flight pressurant inventory; that is not the same mass boundary as site storage.','fluid-faq','linde-space'),
 P('Supply purity, pressure containment, leakage and compatibility shape the equipment. A source bottle, distribution line and flight pressure vessel have different responsibilities and should not be conflated. This workbench does not infer pressure ratings or tank quantities from the rendered commodity symbol. The selected architecture and interface evidence determine which helium functions are actually present.'),
 {suppliers:[supplier('Agency helium-supply contractors','Helium for NASA centers','The linked NASA award is a documented market example. It does not identify a supplier for the selected commercial site.','helium-supply'),supplier('Air Liquide','Space-sector gases and cryogenic services','An additional real industrial supplier example, without an installation claim.','airliquide')],alternatives:[alternative('Helium-based pressure or service system','Use helium where its properties match the approved design.','Requires a compatible supply and pressure-system architecture.'),alternative('Another designed pressurization architecture','Use a different approved gas or vehicle-specific method.','Changes thermal, compatibility and system behavior; gas substitution is an engineering redesign, not a catalog toggle.')],inspection:['Compare site helium supply with any flight pressurant bottle in the parts navigator. They belong to separate inventories and owners.'],terms:[term('Inert gas','A gas with low chemical reactivity under the intended conditions.'),term('Pressurization system','The equipment and gas path used to establish a specified pressure in another volume.')],relatedIds:['site:commodity-services','site:commodity-n2','flight:06.05','flight:06.08']});

Object.assign(groundKnowledgeSources,{
 'ground-glenair-space':source('Space Interconnect Systems for Launch Vehicles, Satellites, and Payloads','Glenair','https://www.glenair.com/space-grade-connector-and-interconnect-cable-solutions/','Supplier technical catalog','Introduces power, signal, RF and data interconnects, including blind-mate and separation interfaces. Product qualification claims apply only to the specified supplier products.'),
 'ground-glenair-release':source('Lanyard-Release Quick-Disconnect Connectors','Glenair','https://www.glenair.com/lanyard-release/','Supplier catalog','A concrete example of electrical umbilical connectors and alternative power, signal and high-speed contact arrangements.'),
 'ground-staubli':source('Advanced Quick Connection Solutions for Launch Site and Rocket','Stäubli','https://www.staubli.com/us/en/fluid-connectors/industries/aerospace-defense/launch-site-rocket.html','Supplier application overview','Examples of custom fluid-connection systems for launch-site, cooling and hydraulic applications. Compatibility with a specific propellant must be separately established.'),
 'ground-osmu-test':source('Orion Service Module Umbilical Testing Wraps Up at Launch Equipment Test Facility','NASA Kennedy','https://www.nasa.gov/blogs/groundsystems/2016/10/21/orion-service-module-umbilical-testing-wraps-up-at-launch-equipment-test-facility/','Test case study','Shows how a real service umbilical was tested against a vehicle-motion simulator, including its environmental-control and coolant functions. It is a historical SLS/Orion example.')
});
umbilicalTopics.fluid=article('umbilical-fluid',
 'This umbilical group organizes one or more ground services at a vehicle interface, including the selected fuel or oxidizer circuit. The group describes the supporting architecture and release behavior; the individual connection pages identify what each line actually carries.',
 P('An umbilical bridges two systems that are temporarily connected: the fixed or mobile ground infrastructure and the vehicle that will depart. It must support its service while connected and reach a clear, defined state at the intended release event. A fuel arm, tail-service assembly and upper-stage arm can meet this need through very different geometries.'),
 P('Fluid paths terminate at controlled interfaces, often alongside supporting mechanical and electrical functions. The group’s structure positions those interfaces relative to the moving vehicle. NASA’s mobile-launcher fact sheet illustrates several real service groups, and its Launch Equipment Test Facility describes the dedicated equipment used to assess ground-to-vehicle mechanisms. These are examples of the engineering problem, not drawings of every launcher.','umbilicals','letf'),
 P('Fluid compatibility and separation geometry are both important. An apparently suitable pipe route can still impose unwanted loads on a connector or obstruct the vehicle after release. Grouped lines should remain individually identifiable by medium and destination. The selected catalog states the architecture, release event and evidence status; where details are inferred, the animation is a conceptual sequence rather than a provider-qualified disconnect demonstration.'),
 {suppliers:[supplier('Stäubli','Launch-site fluid connection systems','A real supplier example of custom couplings and multiconnection equipment. No product compatibility or installed vendor is inferred for this umbilical.','staubli'),supplier('NASA Kennedy Launch Equipment Test Facility','Umbilical and ground-mechanism testing','A documented institutional example of interface verification.','letf')],alternatives:[alternative('Separate service interfaces','Give each medium its own controlled interface and supporting route.','Can simplify individual compatibility boundaries while increasing the number of coordinated connections.'),alternative('Integrated service assembly','Organize several defined circuits within one support or disconnect structure.','Can consolidate geometry, with stronger coupling between mechanical alignment and individual circuit requirements.')],inspection:['Open each child connection to see its medium and endpoints. The group’s release animation applies to the support architecture, not an inferred internal valve design.'],terms:[term('Umbilical','A temporary service connection between ground infrastructure and a vehicle.'),term('Disconnect envelope','The space occupied by an interface and its support while separating and moving clear.')],relatedIds:['site:utility-distribution','site:commodity-services','site:pad-support','launch:vehicle']});
umbilicalTopics.electrical=article('umbilical-electrical',
 'This electrical service group carries the selected ground power, command or data connections to the launch vehicle or payload. It groups circuits by their shared physical interface and release architecture while preserving the distinct purpose of each connection.',
 P('A spacecraft may remain accessible electrically after it is enclosed and mechanically integrated. The service group provides that temporary continuity so teams can monitor status, run approved checks or maintain external power until the campaign reaches its defined handover. Vehicle services and payload services can terminate at different equipment and have different owners.'),
 P('Cables run from ground systems through a controlled connector arrangement to the flight-side interface. The release mechanism later separates that path and leaves the moving vehicle clear. Glenair’s space interconnect and lanyard-release catalogs show actual product families addressing power, signal and high-speed data, while NASA’s umbilical examples show how connectors fit into a larger support structure.','glenair-space','glenair-release','umbilicals'),
 P('Electrical compatibility includes more than matching connector shells. Contact assignments, signal standards, shielding, return paths, power transitions and the state of circuits during disconnect all need a definition. The selected record’s architecture and release event determine how this group fits the sequence. A rendered cable bundle does not establish the pinout or guarantee continuous communications during every movement.'),
 {suppliers:[supplier('Glenair','Launch and space electrical interconnects','A documented example of connectors and cable assemblies. The workbench does not select a connector series or assert compatibility with a particular provider.','glenair-space','glenair-release')],alternatives:[alternative('Separate power and data connectors','Keep circuit families on distinct physical interfaces.','Can simplify separation of electrical requirements while adding mating and release interfaces.'),alternative('Integrated electrical interface','Combine defined contact arrangements in one controlled assembly.','Can reduce interface count, with tighter coordination of pinout, shielding and release behavior.')],inspection:['Follow each cable to its source and destination. A ground electrical umbilical is separate from the payload’s later flight separation connection.'],terms:[term('Pinout','The assignment of electrical functions to connector contacts.'),term('Blind mate','An interface designed to engage through controlled alignment without direct visual access to the contacts.')],relatedIds:['site:utility-distribution','site:connection-payload-power','site:connection-payload-data','site:connection-vehicle-power','site:connection-vehicle-data']});
umbilicalTopics.environmental=article('umbilical-environmental',
 'The payload environmental-service umbilical carries conditioned air to the enclosed payload region before launch. It extends the controlled processing environment into a stage of the campaign when the spacecraft is no longer sitting openly in its integration cleanroom.',
 P('An enclosure protects the payload but also changes its thermal and contamination environment. Air conditioning can help maintain specified conditions around hardware and remove selected ground heat loads. This is a facility-to-enclosure service; it is not automatically a direct coolant connection to the spacecraft’s internal heat-transport system.'),
 P('Conditioned air travels through the provider’s distribution and duct interface into the intended payload volume. The service support must later move clear or disconnect at the defined point in the sequence. Falcon and Ariane payload manuals describe their own payload environments and processing arrangements. NASA’s Orion service-module umbilical test is a separate real example of verifying an environmental-service release mechanism.','falcon','ariane','osmu-test'),
 P('Temperature, humidity, cleanliness and flow distribution all matter to the useful environment at the payload. A supply condition at the ground source does not establish uniform conditions everywhere inside the enclosure. The interface definition must also distinguish conditioned air from nitrogen purge or liquid coolant services. The workbench records the selected medium explicitly instead of treating every environmental duct as the same circuit.'),
 {suppliers:[supplier('Launch provider and payload-processing facility','Payload environmental-control service','The service is part of the selected mission interface. Provider manuals are the starting references; the actual equipment supplier is not established in this model.','falcon','ariane'),supplier('NASA Kennedy','Environmental umbilical verification example','The linked Orion test demonstrates the method class, not a matching interface for every launcher.','osmu-test')],alternatives:[alternative('Enclosure-level conditioned air','Control the environment around the encapsulated spacecraft.','Depends on duct layout, enclosure mixing and the payload’s actual heat sources.'),alternative('Dedicated payload thermal-service interface','Use an explicitly designed direct thermal connection where the provider supports it.','Can target a particular heat path, with additional compatibility and disconnect requirements.')],inspection:['Trace the duct toward the enclosure rather than assuming it enters a flight coolant reservoir.'],terms:[term('Environmental control system','Equipment that maintains specified surrounding conditions such as temperature, humidity and cleanliness.'),term('Encapsulation','Enclosing the payload within its launch enclosure.')],relatedIds:['site:connection-payload-air','site:utility-distribution','launch:fairing','ground:environment','ground:thermal']});

connectionTopics.power=article('connection-power',
 'This connection carries external electrical power from a ground system to the selected vehicle or payload interface. Its exact source, destination and direction are listed in the active design, because launcher power and spacecraft payload power are different service boundaries.',
 P('External power supports preparation and checkout while preserving the intended use of flight batteries. It may remain available through portions of integration when direct access to the hardware is limited. The connection is the physical and electrical boundary, while the ground converter and flight distribution system control what happens on either side.'),
 P('Conductors and contacts carry the intended circuit through a connector assembly. The ground and flight systems must agree on voltage, polarity, return paths and allowed transitions. Provider payload manuals describe electrical accommodation at the mission interface, and Glenair’s catalogs show real power-and-signal connector arrangements used in the wider launch and spacecraft equipment market.','falcon','vulcan','glenair-space'),
 P('Cable drop, connector resistance, transients and the switch to onboard power affect the result at the load. A bonding conductor is not automatically the intended normal power return. The release interface also needs a defined electrical state as contacts separate, rather than being treated as an ordinary unplugged extension cord. The schematic specifies neither a voltage rating nor a pinout; those come from the controlled interface design.'),
 {suppliers:[supplier('Glenair','Space and launch power interconnects','A verified supplier example. The selected pad connector and rating remain unspecified.','glenair-space','glenair-release')],alternatives:[alternative('Dedicated external power interface','Provide a separate controlled ground power path.','Supports sustained checkout but adds a handover and disconnect boundary.'),alternative('Onboard power for a defined campaign interval','Use the vehicle’s approved internal power configuration.','Reduces dependence on an external path while consuming stored energy and changing thermal or recharge needs.')],inspection:['Use the source and destination fields to tell whether this circuit serves the launch vehicle or the spacecraft.'],terms:[term('Power return','The intended path completing a normal electrical power circuit.'),term('Power handover','The transition between external supply and another approved source.')],relatedIds:['site:utility-distribution','ground:power-converter','flight:02.03','flight:02.02']});
connectionTopics.data=article('connection-data',
 'This data connection links ground control or checkout equipment to the selected vehicle or payload electronics. It carries commands, status or mission data through a defined wired interface while the ground and flight systems remain connected.',
 P('A physical cable does not define the meaning of its messages. The connected systems must agree on electrical or optical signaling, packet formats, time references and command authority. For a payload service, the route may include launch-provider interface hardware before it reaches the spacecraft; the active record’s endpoints identify the modeled boundary.'),
 P('Signals pass through a cable assembly and connector arrangement to the receiving electronics. The application layer then interprets commands or telemetry using its agreed definitions. NASA’s ground-system survey explains the relationship between mission-control software and communication interfaces, while Glenair’s catalog illustrates actual high-speed and mixed-signal interconnect options.','ground-ground-data','glenair-space'),
 P('Signal integrity, shielding, timing, grounding and error detection affect reliability. A connection that passes a simple continuity check may still fail at its intended data rate or under the complete integrated configuration. Provider interface documentation is therefore needed alongside functional checkout. The model does not assign Ethernet, a spacecraft bus protocol or an optical link merely because it draws a data-colored line.','falcon'),
 {suppliers:[supplier('Glenair','Signal and high-speed data interconnects','An actual connector and cable supplier example, not an identification of the modeled interface.','glenair-space'),supplier('Terma','Spacecraft checkout and command software','An example of the systems that can use a wired test interface; software and cable compatibility remain separate questions.','terma-checkout')],alternatives:[alternative('Wired service interface','Provide a controlled local command and telemetry route.','Can offer predictable access but requires a physical disconnect and compatible ground routing.'),alternative('Approved radio checkout route','Use the flight radio chain during a defined test or campaign interval.','Includes a different set of hardware and propagation effects, with its own operational interface constraints.')],inspection:['Follow the cable to its intended electronics rather than assuming every data connection reaches the compute payload.'],terms:[term('Signal integrity','Preservation of an electrical signal’s intended waveform and timing through its path.'),term('Protocol','The agreed rules and formats used by communicating systems.')],relatedIds:['site:utility-distribution','ground:avionics','ground:rf','flight:08.01']});
connectionTopics.grounding=article('connection-bond',
 'This bonding connection establishes an intentional electrical relationship between the ground structure and vehicle. Its purpose differs from normal power delivery and from data communication, even when all three appear in the same umbilical group.',
 P('Conductive structures can otherwise sit at different electrical potentials. A defined bond helps control that relationship as part of the broader grounding, electromagnetic-interference and static-control design. Its function must be understood with the complete system; adding a conductor at an arbitrary location does not automatically improve every electrical behavior.'),
 P('The path connects specified conductive features through a controlled interface. Contact quality, attachment geometry and the return network determine how current can flow. NASA Kennedy’s bonding, grounding and EMI standard is a direct reference for the coordination of fixed facilities, portable equipment and sensitive ground systems.','bonding'),
 P('Normal power return, signal reference, cable shielding, protective bonding and lightning-current paths have related but distinct roles. Confusing them can produce unintended current paths or measurement problems. The site lightning article provides a complementary large-scale example, while the individual bond here is a local interface. The workbench does not claim a resistance value, conductor sizing or qualified protection level.','lightning'),
 {suppliers:[supplier('Ground-system electrical integrator','Bonding hardware and coordinated grounding design','The actual hardware supplier is not established. The NASA standard is the relevant engineering reference rather than a product certification.','bonding')],alternatives:[alternative('Dedicated bonding path','Provide an explicitly controlled conductive connection between structures.','Makes the intended relationship visible, with attachment and verification requirements.'),alternative('Designed bonding through structural interfaces','Use an approved structural path as part of the electrical network.','Requires demonstrated electrical continuity and control of coatings, joints and configuration changes.')],inspection:['Keep this line distinct from the power supply return and from signal cables. Its displayed color does not establish an electrical protection rating.'],terms:[term('Grounding','The defined connection of an electrical system or structure to a reference, often including earth.'),term('Electromagnetic interference','Unwanted electromagnetic interaction that can disturb equipment behavior.')],relatedIds:['site:utility-distribution','site:lightning-protection','site:connection-vehicle-power','site:connection-vehicle-data']});
connectionTopics['conditioned-air']=article('connection-air',
 'The conditioned-air connection delivers a controlled environment to the payload enclosure during ground operations. It is the local duct or interface associated with the environmental-service group, rather than a flight coolant line or a generic inert-gas purge.',
 P('Once a spacecraft is enclosed, surrounding air may be an important path for managing ground temperature and cleanliness. The service supports the agreed payload environment through a provider-defined interface. Its effectiveness depends on where the air goes and what heat sources or sensitive surfaces are present inside the enclosure.'),
 P('Air is conditioned upstream and routed through distribution and a disconnectable interface to the payload volume. The payload user guide establishes the provider’s service framework, while the mission interface defines the actual requirements. NASA’s Orion umbilical test supplies a separate real example of a mechanism carrying environmental services and being checked against representative vehicle motion.','falcon','ariane','osmu-test'),
 P('Supply temperature, moisture, cleanliness and flow distribution must be considered together. A cleanroom-compatible source does not guarantee that every downstream duct or surface preserves those conditions. The service ends or changes state at a defined point in the campaign, so the spacecraft’s subsequent thermal condition must be understood without assuming that the ground air remains available in flight.'),
 {suppliers:[supplier('Launch provider and payload-processing operator','Conditioned payload-air service','Actual equipment and requirements are provider- and mission-specific. The workbench does not select an HVAC unit, flow rate or cleanliness class.','falcon','ariane')],alternatives:[alternative('Enclosure air conditioning','Control the environment around the spacecraft.','Can serve a broad volume but depends on mixing, local heat loads and duct routing.'),alternative('Specific direct thermal service','Connect approved cooling equipment to a defined payload thermal interface.','Can address a targeted heat path but adds fluid or conductive-interface requirements distinct from air conditioning.')],inspection:['The destination is the payload environment. Do not infer a connection to a spacecraft liquid loop from the duct’s proximity to a thermal subsystem.'],terms:[term('Supply condition','The specified state of a service at a defined delivery interface.'),term('Environmental handover','The transition between different means of maintaining the payload’s surrounding conditions.')],relatedIds:['site:umbilical-payload-ecs','ground:environment','ground:thermal','launch:fairing']});
connectionTopics.lox=article('connection-lox',
 'This connection is the local ground-to-vehicle interface for liquid oxygen. It belongs to the oxidizer service for the stage identified by the active record and remains distinct from a nearby fuel line, even if both are carried by the same umbilical structure.',
 P('The site supply and the flight tank are separate systems with separate mass and ownership boundaries. Their interface must maintain the specified fluid condition while connected and then reach the intended separated state. That makes the connection both a fluid-engineering problem and a mechanical integration problem.'),
 P('A defined passage joins the ground distribution path to the vehicle-side interface. Real implementations use medium-compatible sealing and support arrangements, with disconnect behavior coordinated through the umbilical group. NASA’s launch-equipment test capabilities describe the verification environment for these interfaces, while Kennedy’s servicing overview explains the broader fluid-system engineering context.','letf','propellants'),
 P('Oxygen compatibility, cleanliness, heat input, relative motion and loads at the mating interface all affect the design. A coupling selected for another fluid cannot be assumed suitable because its bore or exterior shape looks similar. The model intentionally omits valve internals, pressure limits and operating instructions. Its release motion teaches which ground connection clears which vehicle interface, not how an actual oxygen system is serviced.'),
 {suppliers:[supplier('Stäubli','Launch-site fluid connection systems','An actual supplier category example. The cited overview does not establish LOX compatibility for a selected product or identify the installed connector.','staubli'),supplier('NASA Kennedy Launch Equipment Test Facility','Umbilical interface verification','An institutional reference for testing complete mechanisms and service interfaces.','letf')],alternatives:[alternative('Dedicated oxygen disconnect','Provide a separately defined oxygen-compatible interface.','Keeps the medium boundary explicit while adding an individual alignment and release interface.'),alternative('Integrated service carrier with distinct circuits','Mount several separately engineered connections on one support.','Can consolidate motion, with tighter coordination of alignment, loads and individual fluid requirements.')],inspection:['Read the destination to distinguish core, booster and upper-stage oxidizer connections. Repeated LOX lines share a medium but serve different hardware.'],terms:[term('Fluid boundary','The defined interface separating two fluid-system responsibilities or volumes.'),term('Wetted interface','The connector surfaces and materials in direct contact with the fluid.')],relatedIds:['site:commodity-lox','site:commodity-services','site:utility-distribution']});
connectionTopics.methane=article('connection-methane',
 'This connection carries the selected methane fuel service from the ground distribution system to a particular vehicle stage. It is a fuel interface with a defined medium and destination, not a generic hose that can stand in for the oxidizer or any other propellant.',
 P('A launch system may have separate core, booster and upper-stage interfaces even when some of them use the same fuel. Each connection has its own route and release relationship. The active record identifies those endpoints so the reader can follow the actual service topology instead of inferring it from line color.'),
 P('The connector joins the medium-specific ground path to the vehicle interface through controlled sealing and mechanical support. Cryogenic fuel behavior and the specified fuel composition affect the connected system. NASA Glenn’s methane research history provides propulsion context, and NASA Kennedy’s fluid-service overview explains why material compatibility and interface analysis are part of ground-system engineering.','methane-history','propellants'),
 P('The connection must be considered with thermal conditions, relative motion, loads and the required disconnected state. The catalog’s methane medium should not be expanded into an assumed fuel grade or supplier. Similarly, a visible quick-release feature does not establish an internal valve design or allowable pressure. Those details belong to a controlled provider interface and its verification evidence.'),
 {suppliers:[supplier('Stäubli','Custom fluid connections for launch-site applications','A documented example of the equipment class. Compatibility with the actual methane service must be established for a specific product and design.','staubli'),supplier('NASA Kennedy Launch Equipment Test Facility','Ground-to-vehicle interface tests','A reference for the complete mechanism-testing problem, not a certification of this model.','letf')],alternatives:[alternative('Dedicated fuel connection','Engineer an individual medium-specific route and disconnect.','Makes its boundary clear while requiring separate alignment and release coordination.'),alternative('Multicircuit service assembly','Carry the fuel connection alongside other independently defined circuits.','Can share structure, but fluid boundaries and compatibility remain separate.')],inspection:['Follow this fuel line to its stage. Check the neighboring LOX line as a separate article rather than combining their identities.'],terms:[term('Medium','The particular fluid, gas, electrical service or signal carried by a connection.'),term('Relative motion','Movement of the vehicle interface with respect to the supporting ground interface.')],relatedIds:['site:commodity-lng','site:commodity-lox','site:commodity-services','site:utility-distribution']});
connectionTopics.hydrogen=article('connection-hydrogen',
 'This connection joins a ground hydrogen-fuel service to the selected vehicle stage. The interface belongs to a very-low-temperature fuel system and has different compatibility and thermal requirements from a kerosene or methane connection.',
 P('The stage destination is important. A launcher can combine a hydrogen-fueled upper stage with a core using another propellant pair, so the site may contain several distinct fuel-service families. This connection is the local boundary for the hydrogen path, not evidence that every fuel line on the vehicle carries hydrogen.'),
 P('The connected passage preserves the intended fuel path between ground distribution and vehicle hardware. Its sealing, support and thermal arrangement must work with the complete service system and the intended release motion. NASA’s mobile-launcher fact sheet supplies a real example of stage-specific cryogenic umbilicals; Linde’s space-gas overview places hydrogen within the industrial supply chain.','umbilicals','linde-space'),
 P('Heat leakage, contraction, material compatibility and leakage behavior all matter at a cryogenic interface. Mechanical alignment and clear departure geometry remain important alongside those fluid concerns. The model does not provide a connector design, insulation performance or a servicing procedure. The useful learning boundary is how a distinct hydrogen service reaches a particular stage and then disconnects as part of the selected architecture.'),
 {suppliers:[supplier('Launch provider and specialized fluid-equipment suppliers','Hydrogen-compatible service interface','The actual connector supplier is unresolved. Stäubli provides examples of custom launch-site fluid connections, without establishing hydrogen compatibility for this model.','staubli'),supplier('NASA Kennedy','Cryogenic umbilical and interface verification examples','Published infrastructure and test capabilities provide primary references.','umbilicals','letf')],alternatives:[alternative('Dedicated hydrogen interface','Use a separately engineered service connection for the fuel path.','Makes thermal and compatibility requirements explicit at one local boundary.'),alternative('Integrated cryogenic service structure','Support separate fuel and oxidizer circuits within a coordinated mechanism.','Shares geometry and motion while retaining distinct fluid paths and requirements.')],inspection:['Use the connection’s destination to locate the hydrogen-fueled stage. Distinguish its fuel path from the separate oxidizer connection.'],terms:[term('Thermal contraction','Dimensional change as a component cools.'),term('Cryogenic interface','A connection designed for a fluid system operating at very low temperatures.')],relatedIds:['site:commodity-lh2','site:commodity-lox','site:utility-distribution','launch:upper']});
connectionTopics.rp1=article('connection-rp1',
 'This connection carries the modeled RP-1 fuel service to the selected stage. RP-1 is a controlled rocket-grade kerosene, so the connection’s purpose includes preserving the specified fuel path and compatibility rather than merely transporting an unspecified liquid.',
 P('The ground supply, umbilical and vehicle fuel system share an interface but remain separate assemblies. Their agreement includes the fuel identity, connected materials and destination. A repeated booster fuel line is a separate physical route even when it carries the same medium as a core fuel line.'),
 P('The connection provides a passage between the ground distribution and the vehicle-side interface, supported by the selected umbilical architecture. Its disconnect must be evaluated with that support and the vehicle’s intended motion. NASA Kennedy’s servicing capabilities provide the ground-engineering context; Haltermann’s technical article explains why rocket-kerosene composition is a meaningful requirement.','propellants','rp1-development'),
 P('Material compatibility, cleanliness, sealing, pressure boundary and loads at the connector must follow the actual design. A kerosene line has a different thermal problem from a cryogenic hydrogen line, but that does not make a generic industrial fitting automatically suitable. The workbench does not specify bore, connector product, allowable pressure or a loading sequence.'),
 {suppliers:[supplier('Stäubli','Launch-site fluid connection systems','A real supplier example for custom connection equipment; the selected RP-1 interface is not identified as a product from this supplier.','staubli'),supplier('American Hydrocarbons / Haltermann Solutions','RP-1 fuel','A verified example of the supplied commodity, distinct from the manufacturer of the connector.','rp1-product')],alternatives:[alternative('Individual fuel disconnect','Provide a separately controlled fuel-service interface.','Simplifies identification of the fluid boundary while adding a dedicated mating and release point.'),alternative('Fuel interface on a shared service carrier','Combine structural support with other independently defined circuits.','Can reduce duplicated support hardware while coupling mechanical alignment and release behavior.')],inspection:['Keep the fuel manufacturer, connector supplier and launch-provider interface owner conceptually separate. The model establishes none of them from connector appearance.'],terms:[term('Sealing interface','The surfaces and elements that prevent unintended fluid passage at a connection.'),term('Interface owner','The organization responsible for defining and maintaining one side or the agreed boundary of a connection.')],relatedIds:['site:commodity-rp1','site:commodity-kerosene','site:commodity-lox','site:utility-distribution']});

function unresolvedFluid(kind){
 const fuel=kind==='fuel',name=fuel?'fuel':'oxidizer';
 return article('connection-unknown-'+kind,
  'This record reserves a '+name+' service connection whose precise medium or provider interface is not sufficiently established by the available model evidence. Its place in the service topology can still be studied without pretending that a specific fluid or connector design is known.',
  P('A useful architecture model distinguishes a known function from an unresolved implementation. This connection represents the need to deliver '+name+' to the stated vehicle-side destination. Until the medium and interface are controlled, the model cannot responsibly assign wetted materials, thermal insulation, seals or a product rating.'),
  P(fuel?'Possible fuel architectures include kerosene, methane and hydrogen, which differ substantially in state, density and thermal requirements. Those choices are coupled to the engine and stage rather than interchangeable supply options. NASA Kennedy’s fluid-service overview illustrates the breadth of specialist engineering behind such interfaces.':'An oxidizer supplies the reactant paired with the fuel, but different oxidizer systems can impose very different thermal, material and cleanliness requirements. Calling a line “oxidizer” is therefore a functional description rather than a complete fluid specification. NASA Kennedy’s fluid-service overview illustrates the engineering needed to close that definition.','propellants'),
  P('The useful next evidence is a provider-controlled medium definition and ground-to-vehicle interface, followed by the connection’s mechanical support and release requirements. NASA’s GSE standard and launch-equipment testing capabilities explain the documentation and verification context. The rendered line shows an architectural relationship; it is not a fabrication drawing or a validated loading arrangement.','gse','letf'),
  {suppliers:[supplier('Not yet established','Provider-defined '+name+' service interface','No supplier can be assigned responsibly until the medium and requirements are resolved. Stäubli’s launch-site literature is a category example only.','staubli')],alternatives:[alternative('Retain an explicit open interface','Show the service function while leaving unresolved details unassigned.','Preserves architectural visibility without implying procurement or compatibility.'),alternative('Resolve against provider documentation','Replace the open definition with a controlled medium and interface.','Requires actual mission evidence and may change geometry, materials and ground infrastructure.')],inspection:['Read the interface-status field before interpreting the line. Its color and route do not establish the fluid identity.'],terms:[term('Open interface','A required connection whose complete technical definition has not yet been agreed or evidenced.'),term('Architecture allocation','Assignment of a system function before every implementing detail is resolved.')],relatedIds:['site:commodity-services','site:utility-distribution','launch:vehicle']});
}
connectionTopics['unknown-fuel']=unresolvedFluid('fuel');
connectionTopics['unknown-oxidizer']=unresolvedFluid('oxidizer');
connectionTopics.unknown=article('connection-unresolved',
 'This service connection has an architectural role but no recognized detailed medium definition in the current knowledge mapping. The source, destination and evidence status remain useful, while the physical implementation must stay open.',
 P('Service lines can carry fluids, electrical energy, information or an environmental function. Those categories require different hardware and verification. A drawing that connects two objects is a starting point for interface definition, not evidence that a suitable cable, hose or connector has already been selected.'),
 P('A complete connection description identifies what crosses the boundary, in which direction and under which states. It also identifies the supporting structure and whether the connection remains in place or separates during the campaign. NASA’s umbilical references show how several distinct services can be organized within one larger ground-to-vehicle architecture.','umbilicals'),
 P('The next design step is to resolve the medium and interface requirements before assigning detailed materials, capacities or operating limits. NASA’s GSE standard provides a reference for documenting purpose-built ground equipment, and the Launch Equipment Test Facility illustrates the test context for mechanisms that must disconnect near a moving vehicle. These references explain the process without filling evidence gaps by guesswork.','gse','letf'),
 {suppliers:[supplier('Not yet established','Service interface equipment','A credible supplier comparison depends on the resolved medium, interface and verification requirements. No procurement claim is made for this symbolic connection.')],alternatives:[alternative('Keep an explicit unresolved connection','Preserve the required relationship and identify the missing interface evidence.','Supports architecture discussion while limiting detailed analysis.'),alternative('Adopt a verified provider interface','Use a controlled definition for the selected mission.','Enables hardware selection and verification but can alter neighboring systems and routing.')],inspection:['Consult the connection’s source, destination and interface-status fields. The line is an architectural marker until its medium is resolved.'],terms:[term('Interface requirement','A controlled statement of what two connected systems must provide or tolerate.'),term('Verification boundary','The portion of a system included in a particular test or analysis.')],relatedIds:['site:utility-distribution','site:launch-position']});
